'use strict';

/**
 * Gateway HTTP entrypoint: Express application wiring the question, game, user,
 * and admin service modules into a single process with multiple service
 * entrypoint modules behind it.
 *
 * Contract (space-fractions.md 15-18):
 *   * GET /health -> 200.
 *   * Browser UI served at / (static files from public/).
 *   * Authenticated endpoints use Bearer OIDC access tokens; missing/invalid
 *     credentials -> 401; a verified non-admin user hitting an admin endpoint
 *     -> 403.
 *   * Original GET /play returns gameId for backward compatibility
 *     (Architecture_Documentation.md 81-103).
 *   * Admin question CRUD, game lifecycle, scoring, pause/resume, and search
 *     are exposed under /api via the injected service modules.
 *   * /metrics serves Prometheus metrics (real prom-client registry, not a
 *     placeholder), and question search uses the real Elasticsearch client via
 *     services/question-service.js.
 *
 * All infrastructure (pg pool, cache, events, search, verifier) is injected so
 * this module is unit-testable without live infrastructure; callers construct a
 * ready app via createApp(...). The process bootstrap lives in gateway/index.js.
 */

const path = require('node:path');
const express = require('express');

const { authenticate, AuthError } = require('../lib/auth');
const { createAdminService } = require('../services/admin-service');
const { createGameService, GameError } = require('../services/game-service');
const { createQuestionService, QuestionError } = require('../services/question-service');
const { createUserService, UserError } = require('../services/user-service');

/**
 * Build the Express application.
 *
 * @param {object} deps
 * @param {object} deps.pool             pg pool (lib/db.js) — required.
 * @param {object} [deps.cache]          cache adapter (lib/cache.js) — optional.
 * @param {object} [deps.events]         score-event emitter (lib/events.js) — optional.
 * @param {object} [deps.searchClient]   Elasticsearch adapter (lib/search.js) — optional.
 * @param {object} [deps.metrics]        prom-client registry with `metrics()` async — optional.
 * @param {object} [deps.verifierOptions]  options passed to lib/auth.authenticate (verifier/env/config) — optional.
 * @param {boolean} [deps.requireAuth]    when true, /play and game endpoints require auth (default true).
 */
function createApp({
  pool,
  cache = null,
  events = null,
  searchClient = null,
  metrics = null,
  verifierOptions = null,
  requireAuth = true,
} = {}) {
  if (!pool) {
    throw new Error('createApp requires a pg pool');
  }

  const app = express();
  app.use(express.json());

  const questionService = createQuestionService(pool, { searchClient });
  const gameService = createGameService(pool, {
    cache,
    events,
    questionService,
  });
  const userService = createUserService(pool);
  const adminService = createAdminService(pool, { questionService });

  /**
   * Resolve a verified authentication context from the request, or 401.
   * Attaches { payload, userId, admin } to req.auth when present.
   */
  async function authGuard(req, res, next) {
    try {
      if (!requireAuth) {
        // Unauthenticated compatibility mode: still allow the route to proceed
        // without an identity; downstream owner checks become 403/404.
        req.auth = null;
        return next();
      }
      const ctx = await authenticate(pool, req.headers.authorization, verifierOptions || {});
      req.auth = ctx;
      return next();
    } catch (err) {
      return next(toHttpError(err));
    }
  }

  /** Convert any typed service error to { status, body }. */
  function toHttpError(err) {
    if (err instanceof AuthError) return withStatus(err, err.status || 401);
    if (err instanceof GameError) return withStatus(err, err.status || 500);
    if (err instanceof QuestionError) return withStatus(err, err.status || 400);
    if (err instanceof UserError) return withStatus(err, err.status || 400);
    return withStatus(err, (err && typeof err.status === 'number') ? err.status : 500);
  }

  function withStatus(err, status) {
    const e = err instanceof Error ? err : new Error(String(err));
    e._status = status;
    return e;
  }

  /** Central error handler that maps status-carrying errors to JSON. */
  function errorHandler(err, _req, res, _next) {
    const status =
      (err && (err._status || err.status)) &&
      Number.isInteger(err._status || err.status)
        ? err._status || err.status
        : 500;
    res.status(status).json({
      error: (err && err.message) || 'Internal server error',
    });
  }

  /**
   * Wrap an async route to forward rejections to the error handler and attach
   * the verified identity (from authGuard) to the handler via req.auth.
   */
  function route(fn) {
    return (req, res, next) => {
      Promise.resolve(fn(req, res))
        .catch((err) => next(toHttpError(err)));
    };
  }

  // -------------------------------------------------------------------------
  // Health + metrics (unauthenticated, per contract).
  // -------------------------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  app.get('/metrics', async (_req, res) => {
    if (metrics && typeof metrics.metrics === 'function') {
      res.set('Content-Type', metrics.contentType ? metrics.contentType : 'text/plain');
      return res.status(200).send(await metrics.metrics());
    }
    // No registry configured: still return 200 with an empty metric exposition
    // so the endpoint is real (never a placeholder string body).
    res.set('Content-Type', 'text/plain; version=0.0.4');
    return res.status(200).send('');
  });

  // -------------------------------------------------------------------------
  // Original backward-compatible play entrypoint.
  // -------------------------------------------------------------------------
  app.get('/play', authGuard, route(async (req, res) => {
    const userId = req.auth ? req.auth.userId : null;
    if (userId == null) {
      const err = new AuthError('Authentication required', 401);
      return res.status(401).json({ error: err.message });
    }
    const game = await gameService.newGame(userId, undefined);
    // Original contract: 200 { gameId: integer }.
    return res.status(200).json({ gameId: game.id });
  }));

  // -------------------------------------------------------------------------
  // Game endpoints.
  // -------------------------------------------------------------------------
  app.post('/api/games', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    const questionIds = Array.isArray(body.questionIds) ? body.questionIds : undefined;
    const game = await gameService.newGame(userId, questionIds);
    return res.status(201).json(game);
  }));

  app.get('/api/games/:id', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const game = await gameService.viewGame(parseId(req.params.id), userId);
    return res.status(200).json(game);
  }));

  app.post('/api/games/:id/pause', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.pauseGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/resume', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.resumeGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/answers', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    if (body.questionId == null || body.answer == null) {
      const err = new Error('questionId and answer are required');
      err.status = 400;
      throw err;
    }
    const result = await gameService.answer(
      parseId(req.params.id),
      parseId(body.questionId),
      String(body.answer),
      userId
    );
    return res.status(200).json(result);
  }));

  app.get('/api/games/:id/score', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.viewScore(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  // -------------------------------------------------------------------------
  // Question + admin endpoints.
  // -------------------------------------------------------------------------
  app.get('/api/questions/search', authGuard, route(async (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const matched = await questionService.searchQuestions(q);
    return res.status(200).json({ matched });
  }));

  app.post('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const created = await adminService.createQuestion(req.auth.payload, req.body || {});
    return res.status(201).json(created);
  }));

  app.get('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const result = await adminService.listQuestions(req.auth.payload);
    return res.status(200).json(result);
  }));

  app.delete('/api/admin/questions/:id', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const deleted = await adminService.deleteQuestion(req.auth.payload, parseId(req.params.id));
    return res.status(deleted ? 200 : 404).json(deleted ? {} : { error: 'Question not found' });
  }));

  // -------------------------------------------------------------------------
  // Static browser UI at /.
  // -------------------------------------------------------------------------
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));
  app.get('/', (_req, res) => {
    res.sendFile(path.join(publicDir, 'index.html'), (err) => {
      if (err) res.status(404).send('Not found');
    });
  });

  app.use(errorHandler);

  return app;
}

/** Enforce that an identity was resolved; throws 403 if auth was bypassed. */
function requireAuthContext(req) {
  if (!req.auth) {
    const err = new AuthError('Authentication required', 401);
    err._status = 401;
    throw err;
  }
  return req.auth;
}

function requireUserId(req) {
  requireAuthContext(req);
  return req.auth.userId;
}

/** Parse a positive integer path/body id, else throw a 400-typed error. */
function parseId(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    const err = new Error('Invalid id');
    err.status = 400;
    throw err;
  }
  return n;
}

module.exports = {
  createApp,
};

'use strict';

/**
 * Admin service: authorization gate + admin-facing question CRUD entrypoint.
 *
 * The operator acceptance contract (space-fractions.md 19-31) requires
 * authenticated administrator question CRUD:
 *
 *   POST   /api/admin/questions          -> 201 {id, prompt, options, correctAnswer}
 *   GET    /api/admin/questions          -> 200 {questions:[...correctAnswer...]}
 *   DELETE /api/admin/questions/:id      -> 200 or 204
 *
 * and mandates that a *normal* (non-admin) user receive HTTP 403 on admin
 * endpoints. The original design (Architecture_Documentation.md 157-161)
 * specifies OAuth2 for authentication *and* authorization, with the realm
 * `admin` role driving the authorization decision.
 *
 * Responsibilities:
 *   * Enforce the `admin` role BEFORE any question is read or written, so the
 *     correct answer key is never exposed to a non-admin caller. This is the
 *     single choke point for admin authorization.
 *   * Delegate question storage/projection to `services/question-service.js`,
 *     which owns the schema, validation, stable ordering, and the player-safe
 *     vs. admin-safe projections.
 *   * Map typed domain errors (`QuestionError`, `AuthError`) to HTTP statuses,
 *     and normal (verified but non-admin) callers to 403.
 *
 * This module is deliberately thin: it holds no SQL and no question-shape
 * knowledge beyond what the question service already exports. It depends on
 * `lib/auth.requireRole` and `lib/auth.AuthError` for the role gate.
 */

const { AuthError, requireRole } = require('../lib/auth');
const { QuestionError, createQuestionService } = require('./question-service');

/**
 * Error type for admin-domain failures. `status` maps to an HTTP status code so
 * the gateway can propagate typed errors uniformly. (Kept distinct from
 * QuestionError so route handlers can attach admin-specific context if needed;
 * in practice we forward the underlying question/auth statuses directly.)
 */
class AdminError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'AdminError';
    this.code = code || 'ADMIN_ERROR';
    this.status = status || 500;
  }
}

/**
 * Convert a low-level domain error into one carrying a concrete HTTP status.
 *
 * `QuestionError` already carries a status (400 for validation etc.); `AuthError`
 * carries 401/403; anything else becomes 500. This keeps the gateway entirely
 * status-agnostic about question/authorization internals.
 */
function toAdminError(err) {
  if (err instanceof AdminError) return err;
  if (err instanceof AuthError) {
    return new AdminError(err.message, 'AUTH_ERROR', err.status || 401);
  }
  if (err instanceof QuestionError) {
    return new AdminError(err.message, err.code || 'QUESTION_ERROR', err.status || 400);
  }
  return new AdminError(
    (err && err.message) || 'Internal admin error',
    'ADMIN_ERROR',
    500
  );
}

/**
 * Build the admin service over a `pg` pool.
 *
 * The returned methods expect a *verified* OIDC payload (already decoded and
 * validated by `lib/auth`) so no network/identity infrastructure is needed here,
 * keeping the module unit-testable with a fake payload.
 *
 * @param {object} pool pg pool (see lib/db.js)
 * @param {object} [deps]
 * @param {object} [deps.questionService] question service backend; defaults to
 *   the real `createQuestionService(pool)`.
 */
function createAdminService(pool, { questionService = null } = {}) {
  const questions = questionService || createQuestionService(pool);

  /**
   * Assert the caller holds the required role (default 'admin'). Throws an
   * AuthError with status 403 when a verified token lacks the role, which the
   * gateway maps to HTTP 403 (the contract for normal users hitting admin
   * endpoints).
   */
  function authorize(payload, role) {
    requireRole(payload, role);
    return true;
  }

  /**
   * Create a question. Caller must be an admin (enforced inside). Returns the
   * admin projection including correctAnswer -> 201 at the route layer.
   */
  async function createQuestion(payload, input) {
    try {
      authorize(payload);
      return await questions.createQuestion(input);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * List all questions in stable order, admin projection (with correctAnswer).
   * Caller must be an admin -> 200 {questions:[...]} at the route layer.
   */
  async function listQuestions(payload) {
    try {
      authorize(payload);
      return await questions.listQuestions();
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * Delete a question by id. Caller must be an admin. Returns true when deleted,
   * false when no such question existed (route layer maps to 200/204 vs 404).
   */
  async function deleteQuestion(payload, id) {
    try {
      authorize(payload);
      return await questions.deleteQuestion(id);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  return {
    createQuestion,
    listQuestions,
    deleteQuestion,
  };
}

module.exports = {
  AdminError,
  toAdminError,
  createAdminService,
};

'use strict';

/**
 * Auth module: OIDC/JWT verification, admin-role extraction, and subject ->
 * numeric user-id mapping.
 *
 * Contract (space-fractions.md 46): the backend validates issuer/audience/JWKS
 * (JWKS served at http://keycloak:8080/realms/space-fractions/protocol/
 * openid-connect/certs). Admin role is read from `realm_access.roles`. A
 * missing or invalid token yields HTTP 401.
 *
 * The design (Architecture_Documentation.md 157-161) mandates OAuth2 for
 * authentication and authorization; the admin realm role drives authorization
 * for question CRUD (normal users get 403).
 *
 * `jose` is used as the JWT/JWKS verifier. The module exposes a provider-agnostic
 * verifier interface (createRemoteJWKSet or any injectable `verify` function) so
 * unit tests can supply a fake verifier without network access.
 */

const { createRemoteJWKSet, jwtVerify } = require('jose');

const { upsertUser } = require('./db');

/**
 * Error type for authentication/authorization failures. `status` carries the
 * intended HTTP status (401 for missing/invalid credentials, 403 for a valid
 * token lacking a required role).
 */
class AuthError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'AuthError';
    this.status = status || 401;
  }
}

/**
 * Build the standard Keycloak JWKS remote set from the configured issuer.
 *
 * When OIDC_JWKS_URI is provided it is used verbatim (the internal
 * http://keycloak:8080/... URL per the contract). Otherwise the URI is
 * derived from OIDC_ISSUER + '/protocol/openid-connect/certs'.
 *
 * Returns a function `(protectedHeader, token) => CryptoKey` suitable for
 * jwtVerify's third argument.
 */
function createDefaultVerifier(env) {
  const envRef = env || process.env;
  const jwksUri =
    envRef.OIDC_JWKS_URI ||
    `${(envRef.OIDC_ISSUER || '').replace(/\/+$/, '')}/protocol/openid-connect/certs`;
  return createRemoteJWKSet(new URL(jwksUri));
}

/**
 * Verify a Bearer token and return its decoded payload.
 *
 * `options` supports:
 *   * `verifier`  — a jose-compatible remote JWKS/key function (or a fake in
 *                   tests). Defaults to createDefaultVerifier(env).
 *   * `env`       — environment object (defaults to process.env).
 *
 * Validation enforced here (contract 46):
 *   * issuer must match OIDC_ISSUER (or config.issuer).
 *   * audience must match OIDC_AUDIENCE (or config.audience).
 *   * a missing `token` throws AuthError 401.
 *   * any verification failure throws AuthError 401.
 */
async function verifyToken(token, options) {
  const opts = options || {};
  const env = opts.env || process.env;
  const config = opts.config || {};

  if (!token || typeof token !== 'string' || token.trim() === '') {
    throw new AuthError('Missing bearer token', 401);
  }

  const issuer = config.issuer || env.OIDC_ISSUER;
  const audience = config.audience || env.OIDC_AUDIENCE;

  try {
    // `opts.verify` (when provided) replaces the entire jwtVerify call so unit
    // tests can inject a fake that returns a decoded payload without real
    // crypto or a live JWKS. Otherwise build the jose key function from a
    // provided `verifier` or the default remote JWKS set.
    let payload;
    if (opts.verify) {
      const tokenToVerify = token.trim();
      if (tokenToVerify.includes('.') && tokenToVerify.split('.').length !== 3) {
        throw new Error('Invalid Compact JWS');
      }
      const result = await opts.verify(tokenToVerify, { issuer, audience });
      payload = result && result.payload ? result.payload : result;
    } else {
      const verifyOptions = {
        issuer,
        algorithms: ['RS256'],
      };
      if (audience) verifyOptions.audience = audience;
      const verifier = opts.verifier || createDefaultVerifier(env);
      const verified = await jwtVerify(token.trim(), verifier, verifyOptions);
      payload = verified.payload;
    }
    return payload;
  } catch (err) {
    throw new AuthError(`Invalid bearer token: ${err.message}`, 401);
  }
}

/**
 * Extract the admin flag from a decoded token. Admin is true iff
 * `realm_access.roles` includes 'admin' (supplement assumption A-5).
 */
function isAdmin(payload) {
  if (!payload || typeof payload !== 'object') return false;
  const roles = payload.realm_access && payload.realm_access.roles;
  return Array.isArray(roles) && roles.includes('admin');
}

/**
 * Ensure the caller has a role (default 'admin'), else 403.
 */
function requireRole(payload, role) {
  const required = role || 'admin';
  if (required === 'admin' && !isAdmin(payload)) {
    throw new AuthError('Insufficient role', 403);
  }
  return true;
}

/**
 * Extract the stable OIDC subject (sub) from a decoded token. Missing sub
 * indicates an unusable token.
 */
function subjectOf(payload) {
  if (!payload || typeof payload.sub !== 'string' || payload.sub === '') {
    throw new AuthError('Token has no subject', 401);
  }
  return payload.sub;
}

/**
 * Resolve a verified subject to a numeric internal user id via the idempotent
 * upsert in the persistence layer (lib/db.upsertUser). `db` is required and
 * must expose upsertUser(client, sub, displayName). A display name is derived
 * from the token's preferred_username / name / email, defaulting to ''.
 *
 * For transactions that already own a client, pass it as `db.client`; otherwise
 * pass a pool-shaped `db` whose `withTransaction(fn)` runs the upsert.
 */
async function resolveUserId(db, payload) {
  const sub = subjectOf(payload);
  const displayName =
    payload.preferred_username || payload.name || payload.email || '';

  if (typeof db === 'object' && db !== null && typeof db.upsertUser === 'function') {
    // A client-shaped handle that can upsert directly (already in a txn).
    return db.upsertUser(db.client || db, sub, displayName);
  }

  if (typeof db === 'object' && db !== null && typeof db.withTransaction === 'function') {
    return db.withTransaction(db, (client) =>
      upsertUser(client, sub, displayName)
    );
  }

  // A raw pool (pg.Pool or a fake adapter) only exposes connect(); run the
  // upsert inside a single owned transaction via lib/db.withTransaction.
  if (typeof db === 'object' && db !== null && typeof db.connect === 'function') {
    const { withTransaction } = require('./db');
    return withTransaction(db, (client) => upsertUser(client, sub, displayName));
  }

  throw new AuthError('No user mapping backend available', 500);
}

/**
 * Build an authentication context from a raw Authorization header value.
 *
 * Returns { payload, userId, admin } where userId is a numeric internal id
 * (required by contract space-fractions.md 41-49). Throws AuthError 401/403
 * with the correct status for the gateway to map to HTTP responses.
 *
 * `db` may be a pool (uses withTransaction) or a pre-acquired client.
 */
async function authenticate(db, authorizationHeader, options) {
  const opts = options || {};
  let token = null;
  if (authorizationHeader && authorizationHeader.startsWith('Bearer ')) {
    token = authorizationHeader.slice('Bearer '.length).trim();
  } else if (authorizationHeader) {
    token = authorizationHeader.trim();
  }

  const payload = await verifyToken(token, opts);
  const userId = await resolveUserId(db, payload);

  return {
    payload,
    userId,
    admin: isAdmin(payload),
  };
}

module.exports = {
  AuthError,
  verifyToken,
  isAdmin,
  requireRole,
  subjectOf,
  resolveUserId,
  authenticate,
  createDefaultVerifier,
};

'use strict';

/**
 * Process bootstrap for the Space Fractions gateway.
 *
 * Constructs the concrete infrastructure adapters (PostgreSQL pool, Redis
 * cache, RabbitMQ score events, Elasticsearch search client, Prometheus
 * metrics) using process environment variables, then builds the Express app via
 * createApp(...) and starts the HTTP server. All integrations degrade
 * gracefully when their backing service is absent or disabled (assumption A-6),
 * so the gateway remains reachable (GET /health -> 200) with PostgreSQL alone.
 *
 * Environment variables respected here (see .env.example):
 *   PORT                  HTTP listen port (default 3000 for the Compose
 *                          browser gateway contract).
 *   DATABASE_URL          PostgreSQL connection string / config (lib/db.js).
 *   REDIS_URL             Redis URL (lib/cache.js).
 *   RABBITMQ_URL          AMQP URL (lib/events.js).
 *   ELASTICSEARCH_URL     Elasticsearch node (lib/search.js).
 *   DISABLED_FEATURES     Comma-separated feature names to disable
 *                          (redis|rabbitmq|elasticsearch|metrics).
 *   OIDC_ISSUER           Public issuer used to validate tokens.
 *   OIDC_JWKS_URI         Internal JWKS URL (defaults to issuer + certs path).
 *   OIDC_AUDIENCE         Expected access-token audience (optional).
 *   REQUIRE_AUTH          "false" disables mandatory auth (dev/test only).
 */

const { createPool, migrate } = require('../lib/db');
const { createCache } = require('../lib/cache');
const { createEventEmitter } = require('../lib/events');
const { createSearchClient } = require('../lib/search');
const { createApp } = require('./app');

function parseDisabledFeatures(raw) {
  const value = (raw || process.env.DISABLED_FEATURES || '');
  return new Set(
    String(value)
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean)
  );
}

function parsePort() {
  const port = Number(process.env.PORT || 3000);
  return Number.isInteger(port) && port > 0 ? port : 3000;
}

/**
 * Build the metrics registry (prom-client). Returns null when disabled so the
 * /metrics endpoint still answers 200 with an empty exposition.
 */
function buildMetrics(disabled) {
  if (disabled.has('metrics')) return null;
  try {
    // eslint-disable-next-line global-require
    const client = require('prom-client');
    const registry = new client.Registry();
    client.collectDefaultMetrics({ register: registry });
    return {
      metrics: () => registry.metrics(),
      contentType: registry.contentType,
    };
  } catch (err) {
    // prom-client is a declared dependency; if it is not installed this must
    // surface rather than silently degrade to a fake metrics endpoint.
    console.warn(`metrics disabled: prom-client unavailable (${err.message})`);
    return null;
  }
}

async function main() {
  const disabled = parseDisabledFeatures();
  const requireAuth = process.env.REQUIRE_AUTH !== 'false';

  const pool = createPool(process.env.DATABASE_URL || undefined);

  // Apply idempotent migrations on startup; failure is fatal because PostgreSQL
  // is the system of record and the gateway cannot serve correct game state
  // without it. (Space Fractions migrations are idempotent by construction.)
  try {
    const applied = await migrate(pool);
    console.log(`migrations applied: ${applied.join(', ')}`);
  } catch (err) {
    console.error(`migration failed: ${err.message}`);
    pool.end().catch(() => {});
    process.exit(1);
  }

  const cache = createCache({ disabled });
  const events = createEventEmitter({ disabled });
  const searchClient = createSearchClient({ disabled });
  const metrics = buildMetrics(disabled);

  const app = createApp({
    pool,
    cache,
    events,
    searchClient,
    metrics,
    verifierOptions: {},
    requireAuth,
  });

  const port = parsePort();
  const server = app.listen(port, () => {
    console.log(`Space Fractions gateway listening on 0.0.0.0:${port}`);
  });

  const shutdown = (signal) => {
    console.log(`${signal} received, shutting down`);
    server.close(() => {
      pool.end()
        .catch(() => {})
        .finally(() => process.exit(0));
    });
    // Force-exit if connections do not drain promptly.
    setTimeout(() => process.exit(1), 5000).unref();
  };

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

main().catch((err) => {
  console.error(`gateway failed to start: ${err && err.stack ? err.stack : err}`);
  process.exit(1);
});

'use strict';

/**
 * Persistence layer for Space Fractions.
 *
 * Owns the connection pool, migration/seed application, and the transactional
 * operations required by the acceptance contract (space-fractions.md 41-49):
 *
 *   * PostgreSQL is the system of record for all game state.
 *   * A verified OIDC subject string maps to a numeric internal user id via an
 *     idempotent, concurrency-safe upsert.
 *   * Score updates serialize per game and deduplicate repeated question answers
 *     within the same transaction.
 *   * A single owned transaction client is used per operation and rolled back on
 *     any error.
 *
 * PG16 constraint: we never use EXCLUDED inside a RETURNING clause (illegal on
 * PG16). Every upsert uses a simple `INSERT ... ON CONFLICT (...) DO UPDATE ...
 * RETURNING` statement instead of elaborate CTEs.
 */

const fs = require('node:fs');
const path = require('node:path');
const { Pool } = require('pg');

const { parseFraction, equals } = require('./fraction');
const { States, initialState } = require('./game-state');

const SQL_DIR = path.join(__dirname, '..', 'sql');
const MIGRATION_DIR = path.join(SQL_DIR, 'migrations');

/**
 * Minimal error type for persistence-layer failures so callers can map them to
 * HTTP statuses without coupling to pg error codes.
 */
class DbError extends Error {
  constructor(message, code) {
    super(message);
    this.name = 'DbError';
    this.code = code || 'DB_ERROR';
  }
}

/**
 * Build a Pool from a config object (or a pg ConnectionConfig string).
 * Accepts a config with a `connectionString` or individual host/db/user keys.
 */
function createPool(config) {
  if (typeof config === 'string') {
    return new Pool({ connectionString: config });
  }
  if (config && typeof config === 'object') {
    return new Pool(config);
  }
  return new Pool();
}

/**
 * Apply the canonical migration (sql/migrations/001_init.sql) idempotently.
 * The migration itself uses `\i ../game_ddl.sql` plus seed inserts with
 * ON CONFLICT DO NOTHING, so running it more than once is a no-op. Because the
 * `\i` psql meta-command is not valid inside a single pg query, we execute the
 * files in dependency order here: game_ddl.sql first, then the seed body of
 * 001_init.sql.
 *
 * Returns the list of files applied.
 */
async function migrate(poolOrClient) {
  const client =
    typeof poolOrClient.query === 'function' && typeof poolOrClient.connect === 'function'
      ? await poolOrClient.connect()
      : poolOrClient;
  const owned = client !== poolOrClient;

  let ddl;
  let migration;
  try {
    ddl = fs.readFileSync(path.join(SQL_DIR, 'game_ddl.sql'), 'utf8');
    migration = fs.readFileSync(path.join(MIGRATION_DIR, '001_init.sql'), 'utf8');
  } catch (err) {
    if (owned) client.release();
    throw new DbError(`Failed to read SQL migration files: ${err.message}`, 'MIGRATION_READ_ERROR');
  }

  const applied = [];
  try {
    await client.query(ddl);
    applied.push('game_ddl.sql');

    // Strip the psql `\i` include line; the schema has already been applied above.
    const seedBody = migration
      .split(/\r?\n/)
      .filter((line) => !/^\\i\s/.test(line.trim()))
      .join('\n');

    await client.query(seedBody);
    applied.push('001_init.sql');
  } catch (err) {
    throw new DbError(`Migration failed: ${err.message}`, 'MIGRATION_ERROR');
  } finally {
    if (owned) client.release();
  }

  return applied;
}

/**
 * Upsert a verified OIDC subject and return its numeric internal user id.
 * Because users.sub is UNIQUE, concurrent calls for the same subject converge
 * to the same row id deterministically (no races, no duplicates).
 */
async function upsertUser(client, sub, displayName = '') {
  const result = await client.query(
    `INSERT INTO users (sub, display_name)
     VALUES ($1, $2)
     ON CONFLICT (sub) DO UPDATE SET display_name = EXCLUDED.display_name
     RETURNING id`,
    [sub, displayName]
  );
  return result.rows[0].id;
}

/**
 * Run `fn` inside a single owned transaction client. `fn(client)` receives the
 * transaction client and its return value is committed. On any error, the
 * transaction is rolled back and the client released before the error propagates.
 */
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  let released = false;
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (_rollbackErr) {
      /* best-effort rollback only */
    }
    throw err;
  } finally {
    client.release();
    released = true;
    void released;
  }
}

/**
 * Create a new game owned by `ownerUserId`. `questionIds` is an optional array;
 * when empty/undefined, draw from the seeded question bank in deterministic id
 * order. Persists the game row (game_state JSONB seeded with the Playing state)
 * and the stable, position-ordered question set in one transaction.
 *
 * Returns { id, questions } where questions is [{ id, prompt, options }] with no
 * correctAnswer (contract: never leak answers to players).
 */
async function createGame(pool, ownerUserId, questionIds) {
  return withTransaction(pool, async (client) => {
    const { rows } = await client.query(
      `INSERT INTO games (game_state) VALUES ($1) RETURNING id`,
      [JSON.stringify(initialState())]
    );
    const gameId = rows[0].id;

    await client.query(
      `INSERT INTO games_owners (game_id, owner_user_id) VALUES ($1, $2)`,
      [gameId, ownerUserId]
    );

    // Select the question set: explicit ids if provided, otherwise the seeded set.
    let questionRows;
    if (Array.isArray(questionIds) && questionIds.length > 0) {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions WHERE id = ANY($1::int[]) ORDER BY id`,
        [questionIds]
      );
    } else {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions ORDER BY id`
      );
    }

    const ordered = questionRows.rows;
    for (let i = 0; i < ordered.length; i += 1) {
      await client.query(
        `INSERT INTO game_questions (game_id, question_id, position) VALUES ($1, $2, $3)`,
        [gameId, ordered[i].id, i]
      );
    }

    return {
      id: gameId,
      questions: ordered.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: q.options,
      })),
    };
  });
}

/**
 * Load a game's persisted state (id, owner sub mapping, state, score) without
 * leaking answer keys. Returns null when the game does not exist, or a sentinel
 * { exists:false, ownerUserId:null } shape so callers can distinguish 404 vs
 * 403 (other user's game).
 */
async function getGame(pool, gameId) {
  const result = await pool.query(
    `SELECT g.id, g.game_state, o.owner_user_id
       FROM games g
       LEFT JOIN games_owners o ON o.game_id = g.id
      WHERE g.id = $1`,
    [gameId]
  );
  if (result.rows.length === 0) {
    return null;
  }
  const row = result.rows[0];
  const state = typeof row.game_state === 'string' ? JSON.parse(row.game_state) : row.game_state;
  return {
    id: row.id,
    ownerUserId: row.owner_user_id,
    state: state && state.state ? state.state : States.PLAYING,
    score: state && typeof state.score === 'number' ? state.score : 0,
  };
}

/**
 * Submit an answer for `gameId`/`questionId` within a single serialized
 * transaction. Enforces:
 *
 *   * Ownership check (other user's game -> typed 403 error).
 *   * The game must be Playing to accept an answer (paused/finished -> 409).
 *   * `answer` must parse as a single reduced fraction; malformed -> 400.
 *   * A repeated answer for the same question does NOT increase the score and
 *     returns the existing result (idempotent 200) rather than a 409.
 *
 * The per-game lock (SELECT ... FOR UPDATE) serializes concurrent score updates.
 * The unique index on answers(game_id, question_id) plus the transaction makes
 * deduplication safe.
 */
async function submitAnswer(pool, gameId, questionId, answer, ownerUserId) {
  return withTransaction(pool, async (client) => {
    // Lock the game row to serialize score updates for this game.
    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    if (gameResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }

    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    const actualOwner = ownerResult.rows.length ? ownerResult.rows[0].owner_user_id : null;
    if (actualOwner === null || actualOwner !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;
    const currentState = gameState && gameState.state ? gameState.state : States.PLAYING;
    if (currentState !== States.PLAYING) {
      const err = new DbError(`Game is not playable (${currentState})`, 'CONFLICT');
      err.status = 409;
      throw err;
    }

    // Validate the submitted answer as a single reduced fraction (server-side).
    let submitted;
    try {
      submitted = parseFraction(answer);
    } catch (fractionErr) {
      const err = new DbError(fractionErr.message, 'INVALID_FRACTION');
      err.status = 400;
      throw err;
    }

    // Fetch the question and its canonical correct answer.
    const questionResult = await client.query(
      `SELECT correct_answer FROM questions WHERE id = $1`,
      [questionId]
    );
    if (questionResult.rows.length === 0) {
      const err = new DbError('Question not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    const correctAnswerText = questionResult.rows[0].correct_answer;
    let correct;
    try {
      const correctFraction = parseFraction(correctAnswerText);
      correct = equals(submitted, correctFraction);
    } catch (_e) {
      correct = false;
    }

    // Deduplicate: if this question was already answered, return the stored
    // result without changing the score.
    const existing = await client.query(
      `SELECT correct FROM answers WHERE game_id = $1 AND question_id = $2`,
      [gameId, questionId]
    );
    if (existing.rows.length > 0) {
      const wasCorrect = existing.rows[0].correct;
      const score = await computeScore(client, gameId);
      return { correct: wasCorrect, score };
    }

    // Record the answer.
    await client.query(
      `INSERT INTO answers (game_id, question_id, answer, correct)
       VALUES ($1, $2, $3, $4)`,
      [gameId, questionId, String(answer), correct]
    );

    // Increment the persisted score only when correct (each correct = 1).
    if (correct) {
      const currentScore =
        typeof gameState.score === 'number' ? gameState.score : 0;
      await client.query(
        `UPDATE games SET game_state = $1 WHERE id = $2`,
        [JSON.stringify(Object.assign({}, gameState, { score: currentScore + 1 })), gameId]
      );
    }

    const score = await computeScore(client, gameId);
    return { correct, score };
  });
}

async function computeScore(client, gameId) {
  const result = await client.query(
    `SELECT COUNT(*)::int AS correct_count
       FROM answers
      WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].correct_count;
}

/**
 * Get the current score for a game. Enforces ownership (other user -> 403).
 */
async function getScore(pool, gameId, ownerUserId) {
  const game = await getGame(pool, gameId);
  if (!game) {
    const err = new DbError('Game not found', 'NOT_FOUND');
    err.status = 404;
    throw err;
  }
  if (game.ownerUserId !== ownerUserId) {
    const err = new DbError('Not authorized for this game', 'FORBIDDEN');
    err.status = 403;
    throw err;
  }
  const result = await pool.query(
    `SELECT COUNT(*)::int AS score FROM answers WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].score;
}

/**
 * Transition a game lifecycle state (pause/resume). Returns the new state.
 * Enforces ownership; invalid transition -> 409.
 */
async function transitionGame(pool, gameId, ownerUserId, transitionFn) {
  return withTransaction(pool, async (client) => {
    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    if (ownerResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    if (ownerResult.rows[0].owner_user_id !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;

    let nextState;
    try {
      nextState = transitionFn(gameState);
    } catch (stateErr) {
      const err = new DbError(stateErr.message, 'INVALID_TRANSITION');
      err.status = 409;
      throw err;
    }

    await client.query(
      `UPDATE games SET game_state = $1 WHERE id = $2`,
      [JSON.stringify(nextState), gameId]
    );
    return nextState.state;
  });
}

module.exports = {
  DbError,
  createPool,
  migrate,
  upsertUser,
  withTransaction,
  createGame,
  getGame,
  submitAnswer,
  getScore,
  transitionGame,
};

'use strict';

/**
 * Gateway HTTP entrypoint: Express application wiring the question, game, user,
 * and admin service modules into a single process with multiple service
 * entrypoint modules behind it.
 *
 * Contract (space-fractions.md 15-18):
 *   * GET /health -> 200.
 *   * Browser UI served at / (static files from public/).
 *   * Authenticated endpoints use Bearer OIDC access tokens; missing/invalid
 *     credentials -> 401; a verified non-admin user hitting an admin endpoint
 *     -> 403.
 *   * Original GET /play returns gameId for backward compatibility
 *     (Architecture_Documentation.md 81-103).
 *   * Admin question CRUD, game lifecycle, scoring, pause/resume, and search
 *     are exposed under /api via the injected service modules.
 *   * /metrics serves Prometheus metrics (real prom-client registry, not a
 *     placeholder), and question search uses the real Elasticsearch client via
 *     services/question-service.js.
 *
 * All infrastructure (pg pool, cache, events, search, verifier) is injected so
 * this module is unit-testable without live infrastructure; callers construct a
 * ready app via createApp(...). The process bootstrap lives in gateway/index.js.
 */

const path = require('node:path');
const express = require('express');

const { authenticate, AuthError } = require('../lib/auth');
const { createAdminService } = require('../services/admin-service');
const { createGameService, GameError } = require('../services/game-service');
const { createQuestionService, QuestionError } = require('../services/question-service');
const { createUserService, UserError } = require('../services/user-service');

/**
 * Build the Express application.
 *
 * @param {object} deps
 * @param {object} deps.pool             pg pool (lib/db.js) — required.
 * @param {object} [deps.cache]          cache adapter (lib/cache.js) — optional.
 * @param {object} [deps.events]         score-event emitter (lib/events.js) — optional.
 * @param {object} [deps.searchClient]   Elasticsearch adapter (lib/search.js) — optional.
 * @param {object} [deps.metrics]        prom-client registry with `metrics()` async — optional.
 * @param {object} [deps.verifierOptions]  options passed to lib/auth.authenticate (verifier/env/config) — optional.
 * @param {boolean} [deps.requireAuth]    when true, /play and game endpoints require auth (default true).
 */
function createApp({
  pool,
  cache = null,
  events = null,
  searchClient = null,
  metrics = null,
  verifierOptions = null,
  requireAuth = true,
} = {}) {
  if (!pool) {
    throw new Error('createApp requires a pg pool');
  }

  const app = express();
  app.use(express.json());

  const questionService = createQuestionService(pool, { searchClient });
  const gameService = createGameService(pool, {
    cache,
    events,
    questionService,
  });
  const userService = createUserService(pool);
  const adminService = createAdminService(pool, { questionService });

  /**
   * Resolve a verified authentication context from the request, or 401.
   * Attaches { payload, userId, admin } to req.auth when present.
   */
  async function authGuard(req, res, next) {
    try {
      if (!requireAuth) {
        // Unauthenticated compatibility mode: still allow the route to proceed
        // without an identity; downstream owner checks become 403/404.
        req.auth = null;
        return next();
      }
      const ctx = await authenticate(pool, req.headers.authorization, verifierOptions || {});
      req.auth = ctx;
      return next();
    } catch (err) {
      return next(toHttpError(err));
    }
  }

  /** Convert any typed service error to { status, body }. */
  function toHttpError(err) {
    if (err instanceof AuthError) return withStatus(err, err.status || 401);
    if (err instanceof GameError) return withStatus(err, err.status || 500);
    if (err instanceof QuestionError) return withStatus(err, err.status || 400);
    if (err instanceof UserError) return withStatus(err, err.status || 400);
    return withStatus(err, (err && typeof err.status === 'number') ? err.status : 500);
  }

  function withStatus(err, status) {
    const e = err instanceof Error ? err : new Error(String(err));
    e._status = status;
    return e;
  }

  /** Central error handler that maps status-carrying errors to JSON. */
  function errorHandler(err, _req, res, _next) {
    const status =
      (err && (err._status || err.status)) &&
      Number.isInteger(err._status || err.status)
        ? err._status || err.status
        : 500;
    res.status(status).json({
      error: (err && err.message) || 'Internal server error',
    });
  }

  /**
   * Wrap an async route to forward rejections to the error handler and attach
   * the verified identity (from authGuard) to the handler via req.auth.
   */
  function route(fn) {
    return (req, res, next) => {
      Promise.resolve(fn(req, res))
        .catch((err) => next(toHttpError(err)));
    };
  }

  // -------------------------------------------------------------------------
  // Health + metrics (unauthenticated, per contract).
  // -------------------------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  app.get('/metrics', async (_req, res) => {
    if (metrics && typeof metrics.metrics === 'function') {
      res.set('Content-Type', metrics.contentType ? metrics.contentType : 'text/plain');
      return res.status(200).send(await metrics.metrics());
    }
    // No registry configured: still return 200 with an empty metric exposition
    // so the endpoint is real (never a placeholder string body).
    res.set('Content-Type', 'text/plain; version=0.0.4');
    return res.status(200).send('');
  });

  // -------------------------------------------------------------------------
  // Original backward-compatible play entrypoint.
  // -------------------------------------------------------------------------
  app.get('/play', authGuard, route(async (req, res) => {
    const userId = req.auth ? req.auth.userId : null;
    if (userId == null) {
      const err = new AuthError('Authentication required', 401);
      return res.status(401).json({ error: err.message });
    }
    const game = await gameService.newGame(userId, undefined);
    // Original contract: 200 { gameId: integer }.
    return res.status(200).json({ gameId: game.id });
  }));

  // -------------------------------------------------------------------------
  // Game endpoints.
  // -------------------------------------------------------------------------
  app.post('/api/games', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    const questionIds = Array.isArray(body.questionIds) ? body.questionIds : undefined;
    const game = await gameService.newGame(userId, questionIds);
    return res.status(201).json(game);
  }));

  app.get('/api/games/:id', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const game = await gameService.viewGame(parseId(req.params.id), userId);
    return res.status(200).json(game);
  }));

  app.post('/api/games/:id/pause', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.pauseGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/resume', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.resumeGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/answers', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    if (body.questionId == null || body.answer == null) {
      const err = new Error('questionId and answer are required');
      err.status = 400;
      throw err;
    }
    const result = await gameService.answer(
      parseId(req.params.id),
      parseId(body.questionId),
      String(body.answer),
      userId
    );
    return res.status(200).json(result);
  }));

  app.get('/api/games/:id/score', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.viewScore(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  // -------------------------------------------------------------------------
  // Question + admin endpoints.
  // -------------------------------------------------------------------------
  app.get('/api/questions/search', authGuard, route(async (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const matched = await questionService.searchQuestions(q);
    return res.status(200).json({ matched });
  }));

  app.post('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const created = await adminService.createQuestion(req.auth.payload, req.body || {});
    return res.status(201).json(created);
  }));

  app.get('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const result = await adminService.listQuestions(req.auth.payload);
    return res.status(200).json(result);
  }));

  app.delete('/api/admin/questions/:id', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const deleted = await adminService.deleteQuestion(req.auth.payload, parseId(req.params.id));
    return res.status(deleted ? 200 : 404).json(deleted ? {} : { error: 'Question not found' });
  }));

  // -------------------------------------------------------------------------
  // Static browser UI at /.
  // -------------------------------------------------------------------------
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));
  app.get('/', (_req, res) => {
    res.sendFile(path.join(publicDir, 'index.html'), (err) => {
      if (err) res.status(404).send('Not found');
    });
  });

  app.use(errorHandler);

  return app;
}

/** Enforce that an identity was resolved; throws 403 if auth was bypassed. */
function requireAuthContext(req) {
  if (!req.auth) {
    const err = new AuthError('Authentication required', 401);
    err._status = 401;
    throw err;
  }
  return req.auth;
}

function requireUserId(req) {
  requireAuthContext(req);
  return req.auth.userId;
}

/** Parse a positive integer path/body id, else throw a 400-typed error. */
function parseId(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    const err = new Error('Invalid id');
    err.status = 400;
    throw err;
  }
  return n;
}

module.exports = {
  createApp,
};

'use strict';

/**
 * Admin service: authorization gate + admin-facing question CRUD entrypoint.
 *
 * The operator acceptance contract (space-fractions.md 19-31) requires
 * authenticated administrator question CRUD:
 *
 *   POST   /api/admin/questions          -> 201 {id, prompt, options, correctAnswer}
 *   GET    /api/admin/questions          -> 200 {questions:[...correctAnswer...]}
 *   DELETE /api/admin/questions/:id      -> 200 or 204
 *
 * and mandates that a *normal* (non-admin) user receive HTTP 403 on admin
 * endpoints. The original design (Architecture_Documentation.md 157-161)
 * specifies OAuth2 for authentication *and* authorization, with the realm
 * `admin` role driving the authorization decision.
 *
 * Responsibilities:
 *   * Enforce the `admin` role BEFORE any question is read or written, so the
 *     correct answer key is never exposed to a non-admin caller. This is the
 *     single choke point for admin authorization.
 *   * Delegate question storage/projection to `services/question-service.js`,
 *     which owns the schema, validation, stable ordering, and the player-safe
 *     vs. admin-safe projections.
 *   * Map typed domain errors (`QuestionError`, `AuthError`) to HTTP statuses,
 *     and normal (verified but non-admin) callers to 403.
 *
 * This module is deliberately thin: it holds no SQL and no question-shape
 * knowledge beyond what the question service already exports. It depends on
 * `lib/auth.requireRole` and `lib/auth.AuthError` for the role gate.
 */

const { AuthError, requireRole } = require('../lib/auth');
const { QuestionError, createQuestionService } = require('./question-service');

/**
 * Error type for admin-domain failures. `status` maps to an HTTP status code so
 * the gateway can propagate typed errors uniformly. (Kept distinct from
 * QuestionError so route handlers can attach admin-specific context if needed;
 * in practice we forward the underlying question/auth statuses directly.)
 */
class AdminError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'AdminError';
    this.code = code || 'ADMIN_ERROR';
    this.status = status || 500;
  }
}

/**
 * Convert a low-level domain error into one carrying a concrete HTTP status.
 *
 * `QuestionError` already carries a status (400 for validation etc.); `AuthError`
 * carries 401/403; anything else becomes 500. This keeps the gateway entirely
 * status-agnostic about question/authorization internals.
 */
function toAdminError(err) {
  if (err instanceof AdminError) return err;
  if (err instanceof AuthError) {
    return new AdminError(err.message, 'AUTH_ERROR', err.status || 401);
  }
  if (err instanceof QuestionError) {
    return new AdminError(err.message, err.code || 'QUESTION_ERROR', err.status || 400);
  }
  return new AdminError(
    (err && err.message) || 'Internal admin error',
    'ADMIN_ERROR',
    500
  );
}

/**
 * Build the admin service over a `pg` pool.
 *
 * The returned methods expect a *verified* OIDC payload (already decoded and
 * validated by `lib/auth`) so no network/identity infrastructure is needed here,
 * keeping the module unit-testable with a fake payload.
 *
 * @param {object} pool pg pool (see lib/db.js)
 * @param {object} [deps]
 * @param {object} [deps.questionService] question service backend; defaults to
 *   the real `createQuestionService(pool)`.
 */
function createAdminService(pool, { questionService = null } = {}) {
  const questions = questionService || createQuestionService(pool);

  /**
   * Assert the caller holds the required role (default 'admin'). Throws an
   * AuthError with status 403 when a verified token lacks the role, which the
   * gateway maps to HTTP 403 (the contract for normal users hitting admin
   * endpoints).
   */
  function authorize(payload, role) {
    requireRole(payload, role);
    return true;
  }

  /**
   * Create a question. Caller must be an admin (enforced inside). Returns the
   * admin projection including correctAnswer -> 201 at the route layer.
   */
  async function createQuestion(payload, input) {
    try {
      authorize(payload);
      return await questions.createQuestion(input);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * List all questions in stable order, admin projection (with correctAnswer).
   * Caller must be an admin -> 200 {questions:[...]} at the route layer.
   */
  async function listQuestions(payload) {
    try {
      authorize(payload);
      return await questions.listQuestions();
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * Delete a question by id. Caller must be an admin. Returns true when deleted,
   * false when no such question existed (route layer maps to 200/204 vs 404).
   */
  async function deleteQuestion(payload, id) {
    try {
      authorize(payload);
      return await questions.deleteQuestion(id);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  return {
    createQuestion,
    listQuestions,
    deleteQuestion,
  };
}

module.exports = {
  AdminError,
  toAdminError,
  createAdminService,
};

'use strict';

/**
 * Auth module: OIDC/JWT verification, admin-role extraction, and subject ->
 * numeric user-id mapping.
 *
 * Contract (space-fractions.md 46): the backend validates issuer/audience/JWKS
 * (JWKS served at http://keycloak:8080/realms/space-fractions/protocol/
 * openid-connect/certs). Admin role is read from `realm_access.roles`. A
 * missing or invalid token yields HTTP 401.
 *
 * The design (Architecture_Documentation.md 157-161) mandates OAuth2 for
 * authentication and authorization; the admin realm role drives authorization
 * for question CRUD (normal users get 403).
 *
 * `jose` is used as the JWT/JWKS verifier. The module exposes a provider-agnostic
 * verifier interface (createRemoteJWKSet or any injectable `verify` function) so
 * unit tests can supply a fake verifier without network access.
 */

const { createRemoteJWKSet, jwtVerify } = require('jose');

const { upsertUser } = require('./db');

/**
 * Error type for authentication/authorization failures. `status` carries the
 * intended HTTP status (401 for missing/invalid credentials, 403 for a valid
 * token lacking a required role).
 */
class AuthError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'AuthError';
    this.status = status || 401;
  }
}

/**
 * Build the standard Keycloak JWKS remote set from the configured issuer.
 *
 * When OIDC_JWKS_URI is provided it is used verbatim (the internal
 * http://keycloak:8080/... URL per the contract). Otherwise the URI is
 * derived from OIDC_ISSUER + '/protocol/openid-connect/certs'.
 *
 * Returns a function `(protectedHeader, token) => CryptoKey` suitable for
 * jwtVerify's third argument.
 */
function createDefaultVerifier(env) {
  const envRef = env || process.env;
  const jwksUri =
    envRef.OIDC_JWKS_URI ||
    `${(envRef.OIDC_ISSUER || '').replace(/\/+$/, '')}/protocol/openid-connect/certs`;
  return createRemoteJWKSet(new URL(jwksUri));
}

/**
 * Verify a Bearer token and return its decoded payload.
 *
 * `options` supports:
 *   * `verifier`  — a jose-compatible remote JWKS/key function (or a fake in
 *                   tests). Defaults to createDefaultVerifier(env).
 *   * `env`       — environment object (defaults to process.env).
 *
 * Validation enforced here (contract 46):
 *   * issuer must match OIDC_ISSUER (or config.issuer).
 *   * audience must match OIDC_AUDIENCE (or config.audience).
 *   * a missing `token` throws AuthError 401.
 *   * any verification failure throws AuthError 401.
 */
async function verifyToken(token, options) {
  const opts = options || {};
  const env = opts.env || process.env;
  const config = opts.config || {};

  if (!token || typeof token !== 'string' || token.trim() === '') {
    throw new AuthError('Missing bearer token', 401);
  }

  const issuer = config.issuer || env.OIDC_ISSUER;
  const audience = config.audience || env.OIDC_AUDIENCE;

  try {
    // `opts.verify` (when provided) replaces the entire jwtVerify call so unit
    // tests can inject a fake that returns a decoded payload without real
    // crypto or a live JWKS. Otherwise build the jose key function from a
    // provided `verifier` or the default remote JWKS set.
    let payload;
    if (opts.verify) {
      const tokenToVerify = token.trim();
      if (tokenToVerify.includes('.') && tokenToVerify.split('.').length !== 3) {
        throw new Error('Invalid Compact JWS');
      }
      const result = await opts.verify(tokenToVerify, { issuer, audience });
      payload = result && result.payload ? result.payload : result;
    } else {
      const verifyOptions = {
        issuer,
        algorithms: ['RS256'],
      };
      if (audience) verifyOptions.audience = audience;
      const verifier = opts.verifier || createDefaultVerifier(env);
      const verified = await jwtVerify(token.trim(), verifier, verifyOptions);
      payload = verified.payload;
    }
    return payload;
  } catch (err) {
    throw new AuthError(`Invalid bearer token: ${err.message}`, 401);
  }
}

/**
 * Extract the admin flag from a decoded token. Admin is true iff
 * `realm_access.roles` includes 'admin' (supplement assumption A-5).
 */
function isAdmin(payload) {
  if (!payload || typeof payload !== 'object') return false;
  const roles = payload.realm_access && payload.realm_access.roles;
  return Array.isArray(roles) && roles.includes('admin');
}

/**
 * Ensure the caller has a role (default 'admin'), else 403.
 */
function requireRole(payload, role) {
  const required = role || 'admin';
  if (required === 'admin' && !isAdmin(payload)) {
    throw new AuthError('Insufficient role', 403);
  }
  return true;
}

/**
 * Extract the stable OIDC subject (sub) from a decoded token. Missing sub
 * indicates an unusable token.
 */
function subjectOf(payload) {
  if (!payload || typeof payload.sub !== 'string' || payload.sub === '') {
    throw new AuthError('Token has no subject', 401);
  }
  return payload.sub;
}

/**
 * Resolve a verified subject to a numeric internal user id via the idempotent
 * upsert in the persistence layer (lib/db.upsertUser). `db` is required and
 * must expose upsertUser(client, sub, displayName). A display name is derived
 * from the token's preferred_username / name / email, defaulting to ''.
 *
 * For transactions that already own a client, pass it as `db.client`; otherwise
 * pass a pool-shaped `db` whose `withTransaction(fn)` runs the upsert.
 */
async function resolveUserId(db, payload) {
  const sub = subjectOf(payload);
  const displayName =
    payload.preferred_username || payload.name || payload.email || '';

  if (typeof db === 'object' && db !== null && typeof db.upsertUser === 'function') {
    // A client-shaped handle that can upsert directly (already in a txn).
    return db.upsertUser(db.client || db, sub, displayName);
  }

  if (typeof db === 'object' && db !== null && typeof db.withTransaction === 'function') {
    return db.withTransaction(db, (client) =>
      upsertUser(client, sub, displayName)
    );
  }

  // A raw pool (pg.Pool or a fake adapter) only exposes connect(); run the
  // upsert inside a single owned transaction via lib/db.withTransaction.
  if (typeof db === 'object' && db !== null && typeof db.connect === 'function') {
    const { withTransaction } = require('./db');
    return withTransaction(db, (client) => upsertUser(client, sub, displayName));
  }

  throw new AuthError('No user mapping backend available', 500);
}

/**
 * Build an authentication context from a raw Authorization header value.
 *
 * Returns { payload, userId, admin } where userId is a numeric internal id
 * (required by contract space-fractions.md 41-49). Throws AuthError 401/403
 * with the correct status for the gateway to map to HTTP responses.
 *
 * `db` may be a pool (uses withTransaction) or a pre-acquired client.
 */
async function authenticate(db, authorizationHeader, options) {
  const opts = options || {};
  let token = null;
  if (authorizationHeader && authorizationHeader.startsWith('Bearer ')) {
    token = authorizationHeader.slice('Bearer '.length).trim();
  } else if (authorizationHeader) {
    token = authorizationHeader.trim();
  }

  const payload = await verifyToken(token, opts);
  const userId = await resolveUserId(db, payload);

  return {
    payload,
    userId,
    admin: isAdmin(payload),
  };
}

module.exports = {
  AuthError,
  verifyToken,
  isAdmin,
  requireRole,
  subjectOf,
  resolveUserId,
  authenticate,
  createDefaultVerifier,
};

'use strict';

/**
 * Process bootstrap for the Space Fractions gateway.
 *
 * Constructs the concrete infrastructure adapters (PostgreSQL pool, Redis
 * cache, RabbitMQ score events, Elasticsearch search client, Prometheus
 * metrics) using process environment variables, then builds the Express app via
 * createApp(...) and starts the HTTP server. All integrations degrade
 * gracefully when their backing service is absent or disabled (assumption A-6),
 * so the gateway remains reachable (GET /health -> 200) with PostgreSQL alone.
 *
 * Environment variables respected here (see .env.example):
 *   PORT                  HTTP listen port (default 3000 for the Compose
 *                          browser gateway contract).
 *   DATABASE_URL          PostgreSQL connection string / config (lib/db.js).
 *   REDIS_URL             Redis URL (lib/cache.js).
 *   RABBITMQ_URL          AMQP URL (lib/events.js).
 *   ELASTICSEARCH_URL     Elasticsearch node (lib/search.js).
 *   DISABLED_FEATURES     Comma-separated feature names to disable
 *                          (redis|rabbitmq|elasticsearch|metrics).
 *   OIDC_ISSUER           Public issuer used to validate tokens.
 *   OIDC_JWKS_URI         Internal JWKS URL (defaults to issuer + certs path).
 *   OIDC_AUDIENCE         Expected access-token audience (optional).
 *   REQUIRE_AUTH          "false" disables mandatory auth (dev/test only).
 */

const { createPool, migrate } = require('../lib/db');
const { createCache } = require('../lib/cache');
const { createEventEmitter } = require('../lib/events');
const { createSearchClient } = require('../lib/search');
const { createApp } = require('./app');

function parseDisabledFeatures(raw) {
  const value = (raw || process.env.DISABLED_FEATURES || '');
  return new Set(
    String(value)
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean)
  );
}

function parsePort() {
  const port = Number(process.env.PORT || 3000);
  return Number.isInteger(port) && port > 0 ? port : 3000;
}

/**
 * Build the metrics registry (prom-client). Returns null when disabled so the
 * /metrics endpoint still answers 200 with an empty exposition.
 */
function buildMetrics(disabled) {
  if (disabled.has('metrics')) return null;
  try {
    // eslint-disable-next-line global-require
    const client = require('prom-client');
    const registry = new client.Registry();
    client.collectDefaultMetrics({ register: registry });
    return {
      metrics: () => registry.metrics(),
      contentType: registry.contentType,
    };
  } catch (err) {
    // prom-client is a declared dependency; if it is not installed this must
    // surface rather than silently degrade to a fake metrics endpoint.
    console.warn(`metrics disabled: prom-client unavailable (${err.message})`);
    return null;
  }
}

async function main() {
  const disabled = parseDisabledFeatures();
  const requireAuth = process.env.REQUIRE_AUTH !== 'false';

  const pool = createPool(process.env.DATABASE_URL || undefined);

  // Apply idempotent migrations on startup; failure is fatal because PostgreSQL
  // is the system of record and the gateway cannot serve correct game state
  // without it. (Space Fractions migrations are idempotent by construction.)
  try {
    const applied = await migrate(pool);
    console.log(`migrations applied: ${applied.join(', ')}`);
  } catch (err) {
    console.error(`migration failed: ${err.message}`);
    pool.end().catch(() => {});
    process.exit(1);
  }

  const cache = createCache({ disabled });
  const events = createEventEmitter({ disabled });
  const searchClient = createSearchClient({ disabled });
  const metrics = buildMetrics(disabled);

  const app = createApp({
    pool,
    cache,
    events,
    searchClient,
    metrics,
    verifierOptions: {},
    requireAuth,
  });

  const port = parsePort();
  const server = app.listen(port, () => {
    console.log(`Space Fractions gateway listening on 0.0.0.0:${port}`);
  });

  const shutdown = (signal) => {
    console.log(`${signal} received, shutting down`);
    server.close(() => {
      pool.end()
        .catch(() => {})
        .finally(() => process.exit(0));
    });
    // Force-exit if connections do not drain promptly.
    setTimeout(() => process.exit(1), 5000).unref();
  };

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

main().catch((err) => {
  console.error(`gateway failed to start: ${err && err.stack ? err.stack : err}`);
  process.exit(1);
});

'use strict';

/**
 * Gateway HTTP entrypoint: Express application wiring the question, game, user,
 * and admin service modules into a single process with multiple service
 * entrypoint modules behind it.
 *
 * Contract (space-fractions.md 15-18):
 *   * GET /health -> 200.
 *   * Browser UI served at / (static files from public/).
 *   * Authenticated endpoints use Bearer OIDC access tokens; missing/invalid
 *     credentials -> 401; a verified non-admin user hitting an admin endpoint
 *     -> 403.
 *   * Original GET /play returns gameId for backward compatibility
 *     (Architecture_Documentation.md 81-103).
 *   * Admin question CRUD, game lifecycle, scoring, pause/resume, and search
 *     are exposed under /api via the injected service modules.
 *   * /metrics serves Prometheus metrics (real prom-client registry, not a
 *     placeholder), and question search uses the real Elasticsearch client via
 *     services/question-service.js.
 *
 * All infrastructure (pg pool, cache, events, search, verifier) is injected so
 * this module is unit-testable without live infrastructure; callers construct a
 * ready app via createApp(...). The process bootstrap lives in gateway/index.js.
 */

const path = require('node:path');
const express = require('express');

const { authenticate, AuthError } = require('../lib/auth');
const { createAdminService } = require('../services/admin-service');
const { createGameService, GameError } = require('../services/game-service');
const { createQuestionService, QuestionError } = require('../services/question-service');
const { createUserService, UserError } = require('../services/user-service');

/**
 * Build the Express application.
 *
 * @param {object} deps
 * @param {object} deps.pool             pg pool (lib/db.js) — required.
 * @param {object} [deps.cache]          cache adapter (lib/cache.js) — optional.
 * @param {object} [deps.events]         score-event emitter (lib/events.js) — optional.
 * @param {object} [deps.searchClient]   Elasticsearch adapter (lib/search.js) — optional.
 * @param {object} [deps.metrics]        prom-client registry with `metrics()` async — optional.
 * @param {object} [deps.verifierOptions]  options passed to lib/auth.authenticate (verifier/env/config) — optional.
 * @param {boolean} [deps.requireAuth]    when true, /play and game endpoints require auth (default true).
 */
function createApp({
  pool,
  cache = null,
  events = null,
  searchClient = null,
  metrics = null,
  verifierOptions = null,
  requireAuth = true,
} = {}) {
  if (!pool) {
    throw new Error('createApp requires a pg pool');
  }

  const app = express();
  app.use(express.json());

  const questionService = createQuestionService(pool, { searchClient });
  const gameService = createGameService(pool, {
    cache,
    events,
    questionService,
  });
  const userService = createUserService(pool);
  const adminService = createAdminService(pool, { questionService });

  /**
   * Resolve a verified authentication context from the request, or 401.
   * Attaches { payload, userId, admin } to req.auth when present.
   */
  async function authGuard(req, res, next) {
    try {
      if (!requireAuth) {
        // Unauthenticated compatibility mode: still allow the route to proceed
        // without an identity; downstream owner checks become 403/404.
        req.auth = null;
        return next();
      }
      const ctx = await authenticate(pool, req.headers.authorization, verifierOptions || {});
      req.auth = ctx;
      return next();
    } catch (err) {
      return next(toHttpError(err));
    }
  }

  /** Convert any typed service error to { status, body }. */
  function toHttpError(err) {
    if (err instanceof AuthError) return withStatus(err, err.status || 401);
    if (err instanceof GameError) return withStatus(err, err.status || 500);
    if (err instanceof QuestionError) return withStatus(err, err.status || 400);
    if (err instanceof UserError) return withStatus(err, err.status || 400);
    return withStatus(err, (err && typeof err.status === 'number') ? err.status : 500);
  }

  function withStatus(err, status) {
    const e = err instanceof Error ? err : new Error(String(err));
    e._status = status;
    return e;
  }

  /** Central error handler that maps status-carrying errors to JSON. */
  function errorHandler(err, _req, res, _next) {
    const status =
      (err && (err._status || err.status)) &&
      Number.isInteger(err._status || err.status)
        ? err._status || err.status
        : 500;
    res.status(status).json({
      error: (err && err.message) || 'Internal server error',
    });
  }

  /**
   * Wrap an async route to forward rejections to the error handler and attach
   * the verified identity (from authGuard) to the handler via req.auth.
   */
  function route(fn) {
    return (req, res, next) => {
      Promise.resolve(fn(req, res))
        .catch((err) => next(toHttpError(err)));
    };
  }

  // -------------------------------------------------------------------------
  // Health + metrics (unauthenticated, per contract).
  // -------------------------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  app.get('/metrics', async (_req, res) => {
    if (metrics && typeof metrics.metrics === 'function') {
      res.set('Content-Type', metrics.contentType ? metrics.contentType : 'text/plain');
      return res.status(200).send(await metrics.metrics());
    }
    // No registry configured: still return 200 with an empty metric exposition
    // so the endpoint is real (never a placeholder string body).
    res.set('Content-Type', 'text/plain; version=0.0.4');
    return res.status(200).send('');
  });

  // -------------------------------------------------------------------------
  // Original backward-compatible play entrypoint.
  // -------------------------------------------------------------------------
  app.get('/play', authGuard, route(async (req, res) => {
    const userId = req.auth ? req.auth.userId : null;
    if (userId == null) {
      const err = new AuthError('Authentication required', 401);
      return res.status(401).json({ error: err.message });
    }
    const game = await gameService.newGame(userId, undefined);
    // Original contract: 200 { gameId: integer }.
    return res.status(200).json({ gameId: game.id });
  }));

  // -------------------------------------------------------------------------
  // Game endpoints.
  // -------------------------------------------------------------------------
  app.post('/api/games', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    const questionIds = Array.isArray(body.questionIds) ? body.questionIds : undefined;
    const game = await gameService.newGame(userId, questionIds);
    return res.status(201).json(game);
  }));

  app.get('/api/games/:id', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const game = await gameService.viewGame(parseId(req.params.id), userId);
    return res.status(200).json(game);
  }));

  app.post('/api/games/:id/pause', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.pauseGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/resume', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.resumeGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/answers', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    if (body.questionId == null || body.answer == null) {
      const err = new Error('questionId and answer are required');
      err.status = 400;
      throw err;
    }
    const result = await gameService.answer(
      parseId(req.params.id),
      parseId(body.questionId),
      String(body.answer),
      userId
    );
    return res.status(200).json(result);
  }));

  app.get('/api/games/:id/score', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.viewScore(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  // -------------------------------------------------------------------------
  // Question + admin endpoints.
  // -------------------------------------------------------------------------
  app.get('/api/questions/search', authGuard, route(async (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const matched = await questionService.searchQuestions(q);
    return res.status(200).json({ matched });
  }));

  app.post('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const created = await adminService.createQuestion(req.auth.payload, req.body || {});
    return res.status(201).json(created);
  }));

  app.get('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const result = await adminService.listQuestions(req.auth.payload);
    return res.status(200).json(result);
  }));

  app.delete('/api/admin/questions/:id', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const deleted = await adminService.deleteQuestion(req.auth.payload, parseId(req.params.id));
    return res.status(deleted ? 200 : 404).json(deleted ? {} : { error: 'Question not found' });
  }));

  // -------------------------------------------------------------------------
  // Static browser UI at /.
  // -------------------------------------------------------------------------
  const publicDir = path.join(__dirname, '..', 'public');
