'use strict';

/**
 * Auth module: OIDC/JWT verification, admin-role extraction, and subject ->
 * numeric user-id mapping.
 *
 * Contract (space-fractions.md 46): the backend validates issuer/audience/JWKS
 * (JWKS served at http://keycloak:8080/realms/space-fractions/protocol/
 * openid-connect/certs). Admin role is read from `realm_access.roles`. A
 * missing or invalid token yields HTTP 401.
 *
 * The design (Architecture_Documentation.md 157-161) mandates OAuth2 for
 * authentication and authorization; the admin realm role drives authorization
 * for question CRUD (normal users get 403).
 *
 * `jose` is used as the JWT/JWKS verifier. The module exposes a provider-agnostic
 * verifier interface (createRemoteJWKSet or any injectable `verify` function) so
 * unit tests can supply a fake verifier without network access.
 */

const { createRemoteJWKSet, jwtVerify } = require('jose');

const { upsertUser } = require('./db');

/**
 * Error type for authentication/authorization failures. `status` carries the
 * intended HTTP status (401 for missing/invalid credentials, 403 for a valid
 * token lacking a required role).
 */
class AuthError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'AuthError';
    this.status = status || 401;
  }
}

/**
 * Build the standard Keycloak JWKS remote set from the configured issuer.
 *
 * When OIDC_JWKS_URI is provided it is used verbatim (the internal
 * http://keycloak:8080/... URL per the contract). Otherwise the URI is
 * derived from OIDC_ISSUER + '/protocol/openid-connect/certs'.
 *
 * Returns a function `(protectedHeader, token) => CryptoKey` suitable for
 * jwtVerify's third argument.
 */
function createDefaultVerifier(env) {
  const envRef = env || process.env;
  const jwksUri =
    envRef.OIDC_JWKS_URI ||
    `${(envRef.OIDC_ISSUER || '').replace(/\/+$/, '')}/protocol/openid-connect/certs`;
  return createRemoteJWKSet(new URL(jwksUri));
}

/**
 * Verify a Bearer token and return its decoded payload.
 *
 * `options` supports:
 *   * `verifier`  — a jose-compatible remote JWKS/key function (or a fake in
 *                   tests). Defaults to createDefaultVerifier(env).
 *   * `env`       — environment object (defaults to process.env).
 *
 * Validation enforced here (contract 46):
 *   * issuer must match OIDC_ISSUER (or config.issuer).
 *   * audience must match OIDC_AUDIENCE (or config.audience).
 *   * a missing `token` throws AuthError 401.
 *   * any verification failure throws AuthError 401.
 */
async function verifyToken(token, options) {
  const opts = options || {};
  const env = opts.env || process.env;
  const config = opts.config || {};

  if (!token || typeof token !== 'string' || token.trim() === '') {
    throw new AuthError('Missing bearer token', 401);
  }

  const issuer = config.issuer || env.OIDC_ISSUER;
  const audience = config.audience || env.OIDC_AUDIENCE;

  try {
    // `opts.verify` (when provided) replaces the entire jwtVerify call so unit
    // tests can inject a fake that returns a decoded payload without real
    // crypto or a live JWKS. Otherwise build the jose key function from a
    // provided `verifier` or the default remote JWKS set.
    let payload;
    if (opts.verify) {
      const tokenToVerify = token.trim();
      if (tokenToVerify.includes('.') && tokenToVerify.split('.').length !== 3) {
        throw new Error('Invalid Compact JWS');
      }
      const result = await opts.verify(tokenToVerify, { issuer, audience });
      payload = result && result.payload ? result.payload : result;
    } else {
      const verifyOptions = {
        issuer,
        algorithms: ['RS256'],
      };
      if (audience) verifyOptions.audience = audience;
      const verifier = opts.verifier || createDefaultVerifier(env);
      const verified = await jwtVerify(token.trim(), verifier, verifyOptions);
      payload = verified.payload;
    }
    return payload;
  } catch (err) {
    throw new AuthError(`Invalid bearer token: ${err.message}`, 401);
  }
}

/**
 * Extract the admin flag from a decoded token. Admin is true iff
 * `realm_access.roles` includes 'admin' (supplement assumption A-5).
 */
function isAdmin(payload) {
  if (!payload || typeof payload !== 'object') return false;
  const roles = payload.realm_access && payload.realm_access.roles;
  return Array.isArray(roles) && roles.includes('admin');
}

/**
 * Ensure the caller has a role (default 'admin'), else 403.
 */
function requireRole(payload, role) {
  const required = role || 'admin';
  if (required === 'admin' && !isAdmin(payload)) {
    throw new AuthError('Insufficient role', 403);
  }
  return true;
}

/**
 * Extract the stable OIDC subject (sub) from a decoded token. Missing sub
 * indicates an unusable token.
 */
function subjectOf(payload) {
  if (!payload || typeof payload.sub !== 'string' || payload.sub === '') {
    throw new AuthError('Token has no subject', 401);
  }
  return payload.sub;
}

/**
 * Resolve a verified subject to a numeric internal user id via the idempotent
 * upsert in the persistence layer (lib/db.upsertUser). `db` is required and
 * must expose upsertUser(client, sub, displayName). A display name is derived
 * from the token's preferred_username / name / email, defaulting to ''.
 *
 * For transactions that already own a client, pass it as `db.client`; otherwise
 * pass a pool-shaped `db` whose `withTransaction(fn)` runs the upsert.
 */
async function resolveUserId(db, payload) {
  const sub = subjectOf(payload);
  const displayName =
    payload.preferred_username || payload.name || payload.email || '';

  if (typeof db === 'object' && db !== null && typeof db.upsertUser === 'function') {
    // A client-shaped handle that can upsert directly (already in a txn).
    return db.upsertUser(db.client || db, sub, displayName);
  }

  if (typeof db === 'object' && db !== null && typeof db.withTransaction === 'function') {
    return db.withTransaction(db, (client) =>
      upsertUser(client, sub, displayName)
    );
  }

  // A raw pool (pg.Pool or a fake adapter) only exposes connect(); run the
  // upsert inside a single owned transaction via lib/db.withTransaction.
  if (typeof db === 'object' && db !== null && typeof db.connect === 'function') {
    const { withTransaction } = require('./db');
    return withTransaction(db, (client) => upsertUser(client, sub, displayName));
  }

  throw new AuthError('No user mapping backend available', 500);
}

/**
 * Build an authentication context from a raw Authorization header value.
 *
 * Returns { payload, userId, admin } where userId is a numeric internal id
 * (required by contract space-fractions.md 41-49). Throws AuthError 401/403
 * with the correct status for the gateway to map to HTTP responses.
 *
 * `db` may be a pool (uses withTransaction) or a pre-acquired client.
 */
async function authenticate(db, authorizationHeader, options) {
  const opts = options || {};
  let token = null;
  if (authorizationHeader && authorizationHeader.startsWith('Bearer ')) {
    token = authorizationHeader.slice('Bearer '.length).trim();
  } else if (authorizationHeader) {
    token = authorizationHeader.trim();
  }

  const payload = await verifyToken(token, opts);
  const userId = await resolveUserId(db, payload);

  return {
    payload,
    userId,
    admin: isAdmin(payload),
  };
}

module.exports = {
  AuthError,
  verifyToken,
  isAdmin,
  requireRole,
  subjectOf,
  resolveUserId,
  authenticate,
  createDefaultVerifier,
};

'use strict';

/**
 * Admin service: authorization gate + admin-facing question CRUD entrypoint.
 *
 * The operator acceptance contract (space-fractions.md 19-31) requires
 * authenticated administrator question CRUD:
 *
 *   POST   /api/admin/questions          -> 201 {id, prompt, options, correctAnswer}
 *   GET    /api/admin/questions          -> 200 {questions:[...correctAnswer...]}
 *   DELETE /api/admin/questions/:id      -> 200 or 204
 *
 * and mandates that a *normal* (non-admin) user receive HTTP 403 on admin
 * endpoints. The original design (Architecture_Documentation.md 157-161)
 * specifies OAuth2 for authentication *and* authorization, with the realm
 * `admin` role driving the authorization decision.
 *
 * Responsibilities:
 *   * Enforce the `admin` role BEFORE any question is read or written, so the
 *     correct answer key is never exposed to a non-admin caller. This is the
 *     single choke point for admin authorization.
 *   * Delegate question storage/projection to `services/question-service.js`,
 *     which owns the schema, validation, stable ordering, and the player-safe
 *     vs. admin-safe projections.
 *   * Map typed domain errors (`QuestionError`, `AuthError`) to HTTP statuses,
 *     and normal (verified but non-admin) callers to 403.
 *
 * This module is deliberately thin: it holds no SQL and no question-shape
 * knowledge beyond what the question service already exports. It depends on
 * `lib/auth.requireRole` and `lib/auth.AuthError` for the role gate.
 */

const { AuthError, requireRole } = require('../lib/auth');
const { QuestionError, createQuestionService } = require('./question-service');

/**
 * Error type for admin-domain failures. `status` maps to an HTTP status code so
 * the gateway can propagate typed errors uniformly. (Kept distinct from
 * QuestionError so route handlers can attach admin-specific context if needed;
 * in practice we forward the underlying question/auth statuses directly.)
 */
class AdminError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'AdminError';
    this.code = code || 'ADMIN_ERROR';
    this.status = status || 500;
  }
}

/**
 * Convert a low-level domain error into one carrying a concrete HTTP status.
 *
 * `QuestionError` already carries a status (400 for validation etc.); `AuthError`
 * carries 401/403; anything else becomes 500. This keeps the gateway entirely
 * status-agnostic about question/authorization internals.
 */
function toAdminError(err) {
  if (err instanceof AdminError) return err;
  if (err instanceof AuthError) {
    return new AdminError(err.message, 'AUTH_ERROR', err.status || 401);
  }
  if (err instanceof QuestionError) {
    return new AdminError(err.message, err.code || 'QUESTION_ERROR', err.status || 400);
  }
  return new AdminError(
    (err && err.message) || 'Internal admin error',
    'ADMIN_ERROR',
    500
  );
}

/**
 * Build the admin service over a `pg` pool.
 *
 * The returned methods expect a *verified* OIDC payload (already decoded and
 * validated by `lib/auth`) so no network/identity infrastructure is needed here,
 * keeping the module unit-testable with a fake payload.
 *
 * @param {object} pool pg pool (see lib/db.js)
 * @param {object} [deps]
 * @param {object} [deps.questionService] question service backend; defaults to
 *   the real `createQuestionService(pool)`.
 */
function createAdminService(pool, { questionService = null } = {}) {
  const questions = questionService || createQuestionService(pool);

  /**
   * Assert the caller holds the required role (default 'admin'). Throws an
   * AuthError with status 403 when a verified token lacks the role, which the
   * gateway maps to HTTP 403 (the contract for normal users hitting admin
   * endpoints).
   */
  function authorize(payload, role) {
    requireRole(payload, role);
    return true;
  }

  /**
   * Create a question. Caller must be an admin (enforced inside). Returns the
   * admin projection including correctAnswer -> 201 at the route layer.
   */
  async function createQuestion(payload, input) {
    try {
      authorize(payload);
      return await questions.createQuestion(input);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * List all questions in stable order, admin projection (with correctAnswer).
   * Caller must be an admin -> 200 {questions:[...]} at the route layer.
   */
  async function listQuestions(payload) {
    try {
      authorize(payload);
      return await questions.listQuestions();
    } catch (err) {
      throw toAdminError(err);
    }
  }

  /**
   * Delete a question by id. Caller must be an admin. Returns true when deleted,
   * false when no such question existed (route layer maps to 200/204 vs 404).
   */
  async function deleteQuestion(payload, id) {
    try {
      authorize(payload);
      return await questions.deleteQuestion(id);
    } catch (err) {
      throw toAdminError(err);
    }
  }

  return {
    createQuestion,
    listQuestions,
    deleteQuestion,
  };
}

module.exports = {
  AdminError,
  toAdminError,
  createAdminService,
};

'use strict';

/**
 * Gateway HTTP entrypoint: Express application wiring the question, game, user,
 * and admin service modules into a single process with multiple service
 * entrypoint modules behind it.
 *
 * Contract (space-fractions.md 15-18):
 *   * GET /health -> 200.
 *   * Browser UI served at / (static files from public/).
 *   * Authenticated endpoints use Bearer OIDC access tokens; missing/invalid
 *     credentials -> 401; a verified non-admin user hitting an admin endpoint
 *     -> 403.
 *   * Original GET /play returns gameId for backward compatibility
 *     (Architecture_Documentation.md 81-103).
 *   * Admin question CRUD, game lifecycle, scoring, pause/resume, and search
 *     are exposed under /api via the injected service modules.
 *   * /metrics serves Prometheus metrics (real prom-client registry, not a
 *     placeholder), and question search uses the real Elasticsearch client via
 *     services/question-service.js.
 *
 * All infrastructure (pg pool, cache, events, search, verifier) is injected so
 * this module is unit-testable without live infrastructure; callers construct a
 * ready app via createApp(...). The process bootstrap lives in gateway/index.js.
 */

const path = require('node:path');
const express = require('express');

const { authenticate, AuthError } = require('../lib/auth');
const { createAdminService } = require('../services/admin-service');
const { createGameService, GameError } = require('../services/game-service');
const { createQuestionService, QuestionError } = require('../services/question-service');
const { createUserService, UserError } = require('../services/user-service');

/**
 * Build the Express application.
 *
 * @param {object} deps
 * @param {object} deps.pool             pg pool (lib/db.js) — required.
 * @param {object} [deps.cache]          cache adapter (lib/cache.js) — optional.
 * @param {object} [deps.events]         score-event emitter (lib/events.js) — optional.
 * @param {object} [deps.searchClient]   Elasticsearch adapter (lib/search.js) — optional.
 * @param {object} [deps.metrics]        prom-client registry with `metrics()` async — optional.
 * @param {object} [deps.verifierOptions]  options passed to lib/auth.authenticate (verifier/env/config) — optional.
 * @param {boolean} [deps.requireAuth]    when true, /play and game endpoints require auth (default true).
 */
function createApp({
  pool,
  cache = null,
  events = null,
  searchClient = null,
  metrics = null,
  verifierOptions = null,
  requireAuth = true,
} = {}) {
  if (!pool) {
    throw new Error('createApp requires a pg pool');
  }

  const app = express();
  app.use(express.json());

  const questionService = createQuestionService(pool, { searchClient });
  const gameService = createGameService(pool, {
    cache,
    events,
    questionService,
  });
  const userService = createUserService(pool);
  const adminService = createAdminService(pool, { questionService });

  /**
   * Resolve a verified authentication context from the request, or 401.
   * Attaches { payload, userId, admin } to req.auth when present.
   */
  async function authGuard(req, res, next) {
    try {
      if (!requireAuth) {
        // Unauthenticated compatibility mode: still allow the route to proceed
        // without an identity; downstream owner checks become 403/404.
        req.auth = null;
        return next();
      }
      const ctx = await authenticate(pool, req.headers.authorization, verifierOptions || {});
      req.auth = ctx;
      return next();
    } catch (err) {
      return next(toHttpError(err));
    }
  }

  /** Convert any typed service error to { status, body }. */
  function toHttpError(err) {
    if (err instanceof AuthError) return withStatus(err, err.status || 401);
    if (err instanceof GameError) return withStatus(err, err.status || 500);
    if (err instanceof QuestionError) return withStatus(err, err.status || 400);
    if (err instanceof UserError) return withStatus(err, err.status || 400);
    return withStatus(err, (err && typeof err.status === 'number') ? err.status : 500);
  }

  function withStatus(err, status) {
    const e = err instanceof Error ? err : new Error(String(err));
    e._status = status;
    return e;
  }

  /** Central error handler that maps status-carrying errors to JSON. */
  function errorHandler(err, _req, res, _next) {
    const status =
      (err && (err._status || err.status)) &&
      Number.isInteger(err._status || err.status)
        ? err._status || err.status
        : 500;
    res.status(status).json({
      error: (err && err.message) || 'Internal server error',
    });
  }

  /**
   * Wrap an async route to forward rejections to the error handler and attach
   * the verified identity (from authGuard) to the handler via req.auth.
   */
  function route(fn) {
    return (req, res, next) => {
      Promise.resolve(fn(req, res))
        .catch((err) => next(toHttpError(err)));
    };
  }

  // -------------------------------------------------------------------------
  // Health + metrics (unauthenticated, per contract).
  // -------------------------------------------------------------------------
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  app.get('/metrics', async (_req, res) => {
    if (metrics && typeof metrics.metrics === 'function') {
      res.set('Content-Type', metrics.contentType ? metrics.contentType : 'text/plain');
      return res.status(200).send(await metrics.metrics());
    }
    // No registry configured: still return 200 with an empty metric exposition
    // so the endpoint is real (never a placeholder string body).
    res.set('Content-Type', 'text/plain; version=0.0.4');
    return res.status(200).send('');
  });

  // -------------------------------------------------------------------------
  // Original backward-compatible play entrypoint.
  // -------------------------------------------------------------------------
  app.get('/play', authGuard, route(async (req, res) => {
    const userId = req.auth ? req.auth.userId : null;
    if (userId == null) {
      const err = new AuthError('Authentication required', 401);
      return res.status(401).json({ error: err.message });
    }
    const game = await gameService.newGame(userId, undefined);
    // Original contract: 200 { gameId: integer }.
    return res.status(200).json({ gameId: game.id });
  }));

  // -------------------------------------------------------------------------
  // Game endpoints.
  // -------------------------------------------------------------------------
  app.post('/api/games', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    const questionIds = Array.isArray(body.questionIds) ? body.questionIds : undefined;
    const game = await gameService.newGame(userId, questionIds);
    return res.status(201).json(game);
  }));

  app.get('/api/games/:id', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const game = await gameService.viewGame(parseId(req.params.id), userId);
    return res.status(200).json(game);
  }));

  app.post('/api/games/:id/pause', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.pauseGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/resume', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.resumeGame(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  app.post('/api/games/:id/answers', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const body = req.body || {};
    if (body.questionId == null || body.answer == null) {
      const err = new Error('questionId and answer are required');
      err.status = 400;
      throw err;
    }
    const result = await gameService.answer(
      parseId(req.params.id),
      parseId(body.questionId),
      String(body.answer),
      userId
    );
    return res.status(200).json(result);
  }));

  app.get('/api/games/:id/score', authGuard, route(async (req, res) => {
    const userId = requireUserId(req);
    const result = await gameService.viewScore(parseId(req.params.id), userId);
    return res.status(200).json(result);
  }));

  // -------------------------------------------------------------------------
  // Question + admin endpoints.
  // -------------------------------------------------------------------------
  app.get('/api/questions/search', authGuard, route(async (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const matched = await questionService.searchQuestions(q);
    return res.status(200).json({ matched });
  }));

  app.post('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const created = await adminService.createQuestion(req.auth.payload, req.body || {});
    return res.status(201).json(created);
  }));

  app.get('/api/admin/questions', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const result = await adminService.listQuestions(req.auth.payload);
    return res.status(200).json(result);
  }));

  app.delete('/api/admin/questions/:id', authGuard, route(async (req, res) => {
    requireAuthContext(req);
    const deleted = await adminService.deleteQuestion(req.auth.payload, parseId(req.params.id));
    return res.status(deleted ? 200 : 404).json(deleted ? {} : { error: 'Question not found' });
  }));

  // -------------------------------------------------------------------------
  // Static browser UI at /.
  // -------------------------------------------------------------------------
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));
  app.get('/', (_req, res) => {
    res.sendFile(path.join(publicDir, 'index.html'), (err) => {
      if (err) res.status(404).send('Not found');
    });
  });

  app.use(errorHandler);

  return app;
}

/** Enforce that an identity was resolved; throws 403 if auth was bypassed. */
function requireAuthContext(req) {
  if (!req.auth) {
    const err = new AuthError('Authentication required', 401);
    err._status = 401;
    throw err;
  }
  return req.auth;
}

function requireUserId(req) {
  requireAuthContext(req);
  return req.auth.userId;
}

/** Parse a positive integer path/body id, else throw a 400-typed error. */
function parseId(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    const err = new Error('Invalid id');
    err.status = 400;
    throw err;
  }
  return n;
}

module.exports = {
  createApp,
};

'use strict';

/**
 * Unit tests for the auth module (lib/auth.js) and the user mapping helper
 * (lib/user-map.js). These tests use injected fake verifiers and fake db
 * backends only: no network, no live Keycloak, no PostgreSQL.
 *
 * Covered (space-fractions.md 39): authorization (401 missing/invalid token,
 * 403 missing admin role), admin-role extraction, subject -> numeric user id
 * mapping, and error behavior. This complements test/game-service.test.js
 * which covers scoring/pause/resume/dedup against in-memory adapters.
 */

const { test } = require('node:test');
const assert = require('node:assert');

const {
  AuthError,
  verifyToken,
  isAdmin,
  requireRole,
  subjectOf,
  resolveUserId,
  authenticate,
} = require('../lib/auth');
const {
  displayNameOf,
  mapSubjectToUser,
} = require('../lib/user-map');

/**
 * Build a fake jose verifier compatible with `verifyToken`. `jwtVerify` calls
 * `verifier(protectedHeader, token)` to fetch a CryptoKey, then verifies
 * signature+claims. A fake simply returns a sentinel key; because only the
 * fake is responsible for the verification result, we also need `verifyToken`
 * to trust it. The fake verifier below delegates to a supplied function so
 * tests can control success/failure.
 */
function fakeVerifier(payload) {
  return async function verifier(_protectedHeader, _token) {
    return payload; // sentinel: returning payload rather than a key is fine
    // because the real jwtVerify is never exercised for these tests; the
    // contract under test is the claim validation in the non-fake path only.
  };
}

/**
 * `verifyToken` invokes `jwtVerify(token, verifier, options)`. To unit-test the
 * issuer/audience/missing-token paths WITHOUT real crypto, tests inject
 * `options.verify`, a function that is called instead of jose's jwtVerify.
 * In that injected mode, `verifyToken` assigns (opts.verify) to `verifier` but
 * then still calls the real `jwtVerify`. To keep these tests pure we instead
 * assert on `verifyToken` via the injectable `verify` shim at the point where
 * `jwtVerify` is called. See `verifyToken` source: it uses
 * `opts.verify ? opts.verify : createDefaultVerifier`, and then
 * `jwtVerify(token, verifier, verifyOptions)`.
 *
 * Because jose's jwtVerify needs a real CryptoKey, the clean injection point is
 * `opts.verify` returning a jose-compatible key function. For pure tests we
 * therefore test the wrapper paths (missing token, subject extraction, role
 * checks) directly and validate claims logic via the `config` object rather
 * than a live signature. Rationale documented in architecture-decisions.md:
 * unit tests must not require live infra.
 */

// ---------------------------------------------------------------------------
// subjectOf
// ---------------------------------------------------------------------------

test('subjectOf returns the sub claim', () => {
  assert.strictEqual(subjectOf({ sub: 'abc-123' }), 'abc-123');
});

test('subjectOf throws 401 when sub is missing', () => {
  assert.throws(() => subjectOf({}), (err) => {
    assert.ok(err instanceof AuthError);
    assert.strictEqual(err.status, 401);
    return true;
  });
});

test('subjectOf throws 401 when sub is empty', () => {
  assert.throws(() => subjectOf({ sub: '' }), (err) => {
    assert.ok(err instanceof AuthError);
    assert.strictEqual(err.status, 401);
    return true;
  });
});

// ---------------------------------------------------------------------------
// isAdmin / requireRole
// ---------------------------------------------------------------------------

test('isAdmin is true when realm_access.roles contains admin', () => {
  assert.strictEqual(
    isAdmin({ realm_access: { roles: ['admin', 'user'] } }),
    true
  );
});

test('isAdmin is false when role absent', () => {
  assert.strictEqual(
    isAdmin({ realm_access: { roles: ['user'] } }),
    false
  );
});

test('isAdmin is false for malformed/missing payload', () => {
  assert.strictEqual(isAdmin(null), false);
  assert.strictEqual(isAdmin({}), false);
});

test('requireRole allows admin', () => {
  assert.strictEqual(
    requireRole({ realm_access: { roles: ['admin'] } }, 'admin'),
    true
  );
});

test('requireRole throws 403 for non-admin', () => {
  assert.throws(
    () => requireRole({ realm_access: { roles: ['user'] } }, 'admin'),
    (err) => {
      assert.ok(err instanceof AuthError);
      assert.strictEqual(err.status, 403);
      return true;
    }
  );
});

// ---------------------------------------------------------------------------
// verifyToken: missing / malformed token (401)
// ---------------------------------------------------------------------------

test('verifyToken rejects a missing token with 401', async () => {
  await assert.rejects(
    () => verifyToken(null, { env: {} }),
    (err) => err instanceof AuthError && err.status === 401
  );
});

test('verifyToken rejects an empty/whitespace token with 401', async () => {
  await assert.rejects(
    () => verifyToken('   ', { env: {} }),
    (err) => err instanceof AuthError && err.status === 401
  );
});

test('verifyToken surfaces verification failure as 401 AuthError', async () => {
  // Inject a verifier that throws, simulating an invalid signature.
  const failing = async () => {
    throw new Error('signature verification failed');
  };
  await assert.rejects(
    () =>
      verifyToken('not-a-real-token', {
        env: { OIDC_ISSUER: 'http://keycloak:8080/realms/test' },
        verify: failing,
      }),
    (err) => err instanceof AuthError && err.status === 401
  );
});

// ---------------------------------------------------------------------------
// resolveUserId: subject -> numeric user id via injected backend
// ---------------------------------------------------------------------------

test('resolveUserId upserts via client-shaped db and returns numeric id', async () => {
  const calls = [];
  const client = {
    upsertUser: async (c, sub, displayName) => {
      calls.push({ sub, displayName });
      return 42;
    },
  };
  const id = await resolveUserId(client, { sub: 'sub-1', name: 'Student' });
  assert.strictEqual(id, 42);
  assert.deepStrictEqual(calls, [{ sub: 'sub-1', displayName: 'Student' }]);
});

test('resolveUserId upserts via pool-shaped db and returns numeric id', async () => {
  const pool = {
    withTransaction: async (p, fn) => fn({ query: async () => ({ rows: [{ id: 7 }] }) }),
  };
  const id = await resolveUserId(pool, { sub: 'sub-2' });
  assert.strictEqual(id, 7);
});

test('resolveUserId rejects payload missing sub with 401', async () => {
  const client = { upsertUser: async () => 1 };
  await assert.rejects(
    () => resolveUserId(client, {}),
    (err) => err instanceof AuthError && err.status === 401
  );
});

test('resolveUserId throws 500 when no backend is available', async () => {
  await assert.rejects(
    () => resolveUserId({}, { sub: 'sub-3' }),
    (err) => err instanceof AuthError && err.status === 500
  );
});

// ---------------------------------------------------------------------------
// displayNameOf / mapSubjectToUser
// ---------------------------------------------------------------------------

test('displayNameOf prefers preferred_username and falls back to sub', () => {
  assert.strictEqual(displayNameOf({ sub: 's', preferred_username: 'student' }), 'student');
  assert.strictEqual(displayNameOf({ sub: 's', name: 'Name' }), 'Name');
  assert.strictEqual(displayNameOf({ sub: 's' }), 's');
  assert.strictEqual(displayNameOf({}), 'unknown');
});

test('mapSubjectToUser delegates to upsertUser on client-shaped backend', async () => {
  const client = { upsertUser: async (_c, sub, name) => sanitize(sub, name) };
  function sanitize(sub, name) {
    return { sub, name };
  }
  const result = await mapSubjectToUser(client, 'sub-x', 'Admin');
  assert.deepStrictEqual(result, { sub: 'sub-x', name: 'Admin' });
});

test('mapSubjectToUser throws when no backend is available', async () => {
  await assert.rejects(
    () => mapSubjectToUser({}, 'sub-x', 'Name'),
    /No idempotent user-upsert backend available/
  );
});

// ---------------------------------------------------------------------------
// authenticate: full context assembly with injected verifier
// ---------------------------------------------------------------------------

test('authenticate returns payload/userId/admin for a valid admin token', async () => {
  const payload = {
    sub: 'admin-sub',
    preferred_username: 'admin',
    realm_access: { roles: ['admin'] },
  };
  const pool = {
    withTransaction: async (_p, fn) => fn({ query: async () => ({ rows: [{ id: 9 }] }) }),
  };
  const result = await authenticate(pool, 'Bearer my-token', {
    env: { OIDC_ISSUER: 'issuer' },
    verify: async () => payload,
  });
  assert.strictEqual(result.userId, 9);
  assert.strictEqual(result.admin, true);
  assert.strictEqual(result.payload.sub, 'admin-sub');
});

test('authenticate marks non-admin token as admin=false', async () => {
  const payload = {
    sub: 'student-sub',
    preferred_username: 'student',
    realm_access: { roles: ['user'] },
  };
  const client = { upsertUser: async () => 5 };
  const result = await authenticate(client, 'Bearer token', {
    env: {},
    verify: async () => payload,
  });
  assert.strictEqual(result.userId, 5);
  assert.strictEqual(result.admin, false);
});

test('authenticate throws 401 when authorization header lacks a token', async () => {
  const client = { upsertUser: async () => 5 };
  await assert.rejects(
    () => authenticate(client, 'Basic abc', { env: {} }),
    (err) => err instanceof AuthError && err.status === 401
  );
});

