'use strict';

/**
 * Question service: admin CRUD, stable ordering, and player-safe projection.
 *
 * Responsibilities (Architecture_Documentation.md §D "QuestionComponent" and the
 * operator acceptance contract, space-fractions.md 19-31):
 *
 *   * Admin-owned question storage backed by the `questions` table (PostgreSQL).
 *   * Stable question ordering (deterministic ORDER BY id).
 *   * Never include `correctAnswer` in a player-facing response; the correct
 *     answer key is only ever returned on the authenticated admin endpoints.
 *   * Optional Elasticsearch-backed search with a bounded timeout. The search
 *     client is injected so the module remains unit-testable without live
 *     infrastructure and degrades gracefully (authoritative DB fallback) when
 *     the search backend is absent or unavailable.
 *
 * Authorization is NOT enforced here. The owning admin route (services/admin-
 * service.js) performs the `requireRole('admin')` gate before delegating to this
 * module, per the acceptance contract (normal users -> 403 at the route layer).
 */

const { withTransaction, DbError } = require('../lib/db');
const { parseFraction } = require('../lib/fraction');

/** Default bounded timeout for downstream search calls (milliseconds). */
const DEFAULT_SEARCH_TIMEOUT_MS = 500;

/**
 * Error type for question-domain failures. `status` maps to an HTTP status code
 * so route handlers can propagate typed errors without inspecting SQL codes.
 */
class QuestionError extends Error {
  constructor(message, code, status) {
    super(message);
    this.name = 'QuestionError';
    this.code = code || 'QUESTION_ERROR';
    this.status = status || 400;
  }
}

/**
 * Validate a question payload before it is written.
 *
 *   prompt       -> non-empty string
 *   options      -> array of strings (at least one option)
 *   correctAnswer -> parseable single reduced fraction (server-side validation)
 *
 * Throws QuestionError (status 400) on any violation.
 */
function validateQuestion({ prompt, options, correctAnswer }) {
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new QuestionError('prompt must be a non-empty string', 'INVALID_PROMPT', 400);
  }
  if (!Array.isArray(options) || options.length === 0) {
    throw new QuestionError('options must be a non-empty array', 'INVALID_OPTIONS', 400);
  }
  for (const opt of options) {
    if (typeof opt !== 'string') {
      throw new QuestionError('each option must be a string', 'INVALID_OPTIONS', 400);
    }
  }
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new QuestionError('correctAnswer must be a non-empty string', 'INVALID_ANSWER', 400);
  }
  // Enforce the exact-rational-arithmetic contract at the boundary.
  try {
    parseFraction(correctAnswer);
  } catch (fractionErr) {
    throw new QuestionError(
      `correctAnswer is not a valid reduced fraction: ${fractionErr.message}`,
      'INVALID_ANSWER',
      400
    );
  }
}

/**
 * Convert a `questions` table row into the admin-facing shape.
 * Includes correctAnswer (callers must be behind the admin authorization gate).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
    correctAnswer: row.correct_answer,
  };
}

/**
 * Convert a `questions` table row into the player-facing shape.
 * NEVER includes correctAnswer.
 */
function toPublicQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: typeof row.options === 'string' ? JSON.parse(row.options) : row.options,
  };
}

/**
 * Build the question service over a `pg` pool and an optional search backend.
 *
 * `searchClient` is an adapter implementing:
 *   search(query) -> Promise<Array<{id, prompt}>>  (already public-safe)
 * `searchTimeoutMs` bounds the downstream call; on timeout or backend failure we
 * fall back to a database LIKE query so search remains authoritative and correct
 * even when Elasticsearch is unavailable.
 *
 * The returned methods never surface `correct_answer` unless explicitly part of
 * the admin contract.
 */
function createQuestionService(pool, { searchClient = null, searchTimeoutMs = DEFAULT_SEARCH_TIMEOUT_MS } = {}) {
  /**
   * Create a question. Returns the admin projection (including correctAnswer).
   */
  async function createQuestion(input) {
    validateQuestion(input);
    const optionsJson = JSON.stringify(input.options);
    const result = await pool.query(
      `INSERT INTO questions (prompt, options, correct_answer)
       VALUES ($1, $2, $3)
       RETURNING id, prompt, options, correct_answer`,
      [input.prompt.trim(), optionsJson, formatCorrectAnswer(input.correctAnswer)]
    );
    return toAdminQuestion(result.rows[0]);
  }

  /**
   * List all questions in stable (id) order. Returns the admin projection:
   * { questions: [{ id, prompt, options, correctAnswer }] }.
   */
  async function listQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options, correct_answer
         FROM questions
        ORDER BY id`
    );
    return { questions: result.rows.map(toAdminQuestion) };
  }

  /**
   * List questions in the public (player-facing) shape, stable id order, never
   * including correctAnswer.
   */
  async function listPublicQuestions() {
    const result = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        ORDER BY id`
    );
    return result.rows.map(toPublicQuestion);
  }

  /**
   * Fetch a single public question (no correctAnswer). Returns null if missing.
   */
  async function getPublicQuestion(id) {
    const result = await pool.query(
      `SELECT id, prompt, options FROM questions WHERE id = $1`,
      [id]
    );
    return result.rows.length ? toPublicQuestion(result.rows[0]) : null;
  }

  /**
   * Delete a question by id. Returns true when a row was deleted, false when no
   * such question existed.
   */
  async function deleteQuestion(id) {
    const result = await pool.query(
      `DELETE FROM questions WHERE id = $1 RETURNING id`,
      [id]
    );
    return result.rows.length > 0;
  }

  /**
   * Search questions by a plain-text query.
   *
   * Prefers the injected Elasticsearch client with a bounded timeout; on any
   * failure (absence, timeout, error) it falls back to an authoritative DB
   * `ILIKE` search so search never returns stale/empty results silently. Results
   * are always the public projection (no correctAnswer).
   */
  async function searchQuestions(query) {
    if (typeof query !== 'string' || query.trim() === '') {
      return [];
    }
    const term = query.trim();

    if (searchClient && typeof searchClient.search === 'function') {
      const result = await withTimeout(
        Promise.resolve(searchClient.search(term)),
        searchTimeoutMs
      );
      if (result && Array.isArray(result.matched)) {
        return result.matched.map((q) => toPublicQuestion(q));
      }
    }

    // Authoritative DB fallback (bounded to id order for stable results).
    const dbResult = await pool.query(
      `SELECT id, prompt, options
         FROM questions
        WHERE prompt ILIKE $1
        ORDER BY id`,
      [`%${escapeLike(term)}%`]
    );
    return dbResult.rows.map(toPublicQuestion);
  }

  return {
    createQuestion,
    listQuestions,
    listPublicQuestions,
    getPublicQuestion,
    deleteQuestion,
    searchQuestions,
  };
}

/**
 * Normalize a correct answer to the canonical single reduced fraction string so
 * the stored value always satisfies the DB CHECK constraint and the same
 * validator used at runtime. Preserves original sign/whole-number forms but
 * reduces where possible (e.g. "2/4" -> "1/2").
 */
function formatCorrectAnswer(answer) {
  const f = parseFraction(answer);
  // Re-render via reduce to guarantee reduced gcd = 1 form ("n/d").
  return `${f.numerator}/${f.denominator}`;
}

/** Escape `%`/`_` so an ILIKE pattern matches the literal term only. */
function escapeLike(term) {
  return term.replace(/[\\%_]/g, (c) => `\\${c}`);
}

/**
 * Bound a promise to a timeout, resolving the fallback (undefined) rather than
 * throwing so callers can degrade gracefully.
 */
function withTimeout(promise, ms) {
  return new Promise((resolve) => {
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(undefined);
      }
    }, ms);
    promise
      .then((val) => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(val);
        }
      })
      .catch(() => {
        if (!done) {
          done = true;
          clearTimeout(timer);
          resolve(undefined);
        }
      });
  });
}

module.exports = {
  QuestionError,
  validateQuestion,
  toAdminQuestion,
  toPublicQuestion,
  createQuestionService,
  DEFAULT_SEARCH_TIMEOUT_MS,
};

'use strict';

/**
 * Persistence layer for Space Fractions.
 *
 * Owns the connection pool, migration/seed application, and the transactional
 * operations required by the acceptance contract (space-fractions.md 41-49):
 *
 *   * PostgreSQL is the system of record for all game state.
 *   * A verified OIDC subject string maps to a numeric internal user id via an
 *     idempotent, concurrency-safe upsert.
 *   * Score updates serialize per game and deduplicate repeated question answers
 *     within the same transaction.
 *   * A single owned transaction client is used per operation and rolled back on
 *     any error.
 *
 * PG16 constraint: we never use EXCLUDED inside a RETURNING clause (illegal on
 * PG16). Every upsert uses a simple `INSERT ... ON CONFLICT (...) DO UPDATE ...
 * RETURNING` statement instead of elaborate CTEs.
 */

const fs = require('node:fs');
const path = require('node:path');
const { Pool } = require('pg');

const { parseFraction, equals } = require('./fraction');
const { States, initialState } = require('./game-state');

const SQL_DIR = path.join(__dirname, '..', 'sql');
const MIGRATION_DIR = path.join(SQL_DIR, 'migrations');

/**
 * Minimal error type for persistence-layer failures so callers can map them to
 * HTTP statuses without coupling to pg error codes.
 */
class DbError extends Error {
  constructor(message, code) {
    super(message);
    this.name = 'DbError';
    this.code = code || 'DB_ERROR';
  }
}

/**
 * Build a Pool from a config object (or a pg ConnectionConfig string).
 * Accepts a config with a `connectionString` or individual host/db/user keys.
 */
function createPool(config) {
  if (typeof config === 'string') {
    return new Pool({ connectionString: config });
  }
  if (config && typeof config === 'object') {
    return new Pool(config);
  }
  return new Pool();
}

/**
 * Apply the canonical migration (sql/migrations/001_init.sql) idempotently.
 * The migration itself uses `\i ../game_ddl.sql` plus seed inserts with
 * ON CONFLICT DO NOTHING, so running it more than once is a no-op. Because the
 * `\i` psql meta-command is not valid inside a single pg query, we execute the
 * files in dependency order here: game_ddl.sql first, then the seed body of
 * 001_init.sql.
 *
 * Returns the list of files applied.
 */
async function migrate(poolOrClient) {
  const client =
    typeof poolOrClient.query === 'function' && typeof poolOrClient.connect === 'function'
      ? await poolOrClient.connect()
      : poolOrClient;
  const owned = client !== poolOrClient;

  let ddl;
  let migration;
  try {
    ddl = fs.readFileSync(path.join(SQL_DIR, 'game_ddl.sql'), 'utf8');
    migration = fs.readFileSync(path.join(MIGRATION_DIR, '001_init.sql'), 'utf8');
  } catch (err) {
    if (owned) client.release();
    throw new DbError(`Failed to read SQL migration files: ${err.message}`, 'MIGRATION_READ_ERROR');
  }

  const applied = [];
  try {
    await client.query(ddl);
    applied.push('game_ddl.sql');

    // Strip the psql `\i` include line; the schema has already been applied above.
    const seedBody = migration
      .split(/\r?\n/)
      .filter((line) => !/^\\i\s/.test(line.trim()))
      .join('\n');

    await client.query(seedBody);
    applied.push('001_init.sql');
  } catch (err) {
    throw new DbError(`Migration failed: ${err.message}`, 'MIGRATION_ERROR');
  } finally {
    if (owned) client.release();
  }

  return applied;
}

/**
 * Upsert a verified OIDC subject and return its numeric internal user id.
 * Because users.sub is UNIQUE, concurrent calls for the same subject converge
 * to the same row id deterministically (no races, no duplicates).
 */
async function upsertUser(client, sub, displayName = '') {
  const result = await client.query(
    `INSERT INTO users (sub, display_name)
     VALUES ($1, $2)
     ON CONFLICT (sub) DO UPDATE SET display_name = EXCLUDED.display_name
     RETURNING id`,
    [sub, displayName]
  );
  return result.rows[0].id;
}

/**
 * Run `fn` inside a single owned transaction client. `fn(client)` receives the
 * transaction client and its return value is committed. On any error, the
 * transaction is rolled back and the client released before the error propagates.
 */
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  let released = false;
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (_rollbackErr) {
      /* best-effort rollback only */
    }
    throw err;
  } finally {
    client.release();
    released = true;
    void released;
  }
}

/**
 * Create a new game owned by `ownerUserId`. `questionIds` is an optional array;
 * when empty/undefined, draw from the seeded question bank in deterministic id
 * order. Persists the game row (game_state JSONB seeded with the Playing state)
 * and the stable, position-ordered question set in one transaction.
 *
 * Returns { id, questions } where questions is [{ id, prompt, options }] with no
 * correctAnswer (contract: never leak answers to players).
 */
async function createGame(pool, ownerUserId, questionIds) {
  return withTransaction(pool, async (client) => {
    const { rows } = await client.query(
      `INSERT INTO games (game_state) VALUES ($1) RETURNING id`,
      [JSON.stringify(initialState())]
    );
    const gameId = rows[0].id;

    await client.query(
      `INSERT INTO games_owners (game_id, owner_user_id) VALUES ($1, $2)`,
      [gameId, ownerUserId]
    );

    // Select the question set: explicit ids if provided, otherwise the seeded set.
    let questionRows;
    if (Array.isArray(questionIds) && questionIds.length > 0) {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions WHERE id = ANY($1::int[]) ORDER BY id`,
        [questionIds]
      );
    } else {
      questionRows = await client.query(
        `SELECT id, prompt, options FROM questions ORDER BY id`
      );
    }

    const ordered = questionRows.rows;
    for (let i = 0; i < ordered.length; i += 1) {
      await client.query(
        `INSERT INTO game_questions (game_id, question_id, position) VALUES ($1, $2, $3)`,
        [gameId, ordered[i].id, i]
      );
    }

    return {
      id: gameId,
      questions: ordered.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: q.options,
      })),
    };
  });
}

/**
 * Load a game's persisted state (id, owner sub mapping, state, score) without
 * leaking answer keys. Returns null when the game does not exist, or a sentinel
 * { exists:false, ownerUserId:null } shape so callers can distinguish 404 vs
 * 403 (other user's game).
 */
async function getGame(pool, gameId) {
  const result = await pool.query(
    `SELECT g.id, g.game_state, o.owner_user_id
       FROM games g
       LEFT JOIN games_owners o ON o.game_id = g.id
      WHERE g.id = $1`,
    [gameId]
  );
  if (result.rows.length === 0) {
    return null;
  }
  const row = result.rows[0];
  const state = typeof row.game_state === 'string' ? JSON.parse(row.game_state) : row.game_state;
  return {
    id: row.id,
    ownerUserId: row.owner_user_id,
    state: state && state.state ? state.state : States.PLAYING,
    score: state && typeof state.score === 'number' ? state.score : 0,
  };
}

/**
 * Submit an answer for `gameId`/`questionId` within a single serialized
 * transaction. Enforces:
 *
 *   * Ownership check (other user's game -> typed 403 error).
 *   * The game must be Playing to accept an answer (paused/finished -> 409).
 *   * `answer` must parse as a single reduced fraction; malformed -> 400.
 *   * A repeated answer for the same question does NOT increase the score and
 *     returns the existing result (idempotent 200) rather than a 409.
 *
 * The per-game lock (SELECT ... FOR UPDATE) serializes concurrent score updates.
 * The unique index on answers(game_id, question_id) plus the transaction makes
 * deduplication safe.
 */
async function submitAnswer(pool, gameId, questionId, answer, ownerUserId) {
  return withTransaction(pool, async (client) => {
    // Lock the game row to serialize score updates for this game.
    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    if (gameResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }

    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    const actualOwner = ownerResult.rows.length ? ownerResult.rows[0].owner_user_id : null;
    if (actualOwner === null || actualOwner !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;
    const currentState = gameState && gameState.state ? gameState.state : States.PLAYING;
    if (currentState !== States.PLAYING) {
      const err = new DbError(`Game is not playable (${currentState})`, 'CONFLICT');
      err.status = 409;
      throw err;
    }

    // Validate the submitted answer as a single reduced fraction (server-side).
    let submitted;
    try {
      submitted = parseFraction(answer);
    } catch (fractionErr) {
      const err = new DbError(fractionErr.message, 'INVALID_FRACTION');
      err.status = 400;
      throw err;
    }

    // Fetch the question and its canonical correct answer.
    const questionResult = await client.query(
      `SELECT correct_answer FROM questions WHERE id = $1`,
      [questionId]
    );
    if (questionResult.rows.length === 0) {
      const err = new DbError('Question not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    const correctAnswerText = questionResult.rows[0].correct_answer;
    let correct;
    try {
      const correctFraction = parseFraction(correctAnswerText);
      correct = equals(submitted, correctFraction);
    } catch (_e) {
      correct = false;
    }

    // Deduplicate: if this question was already answered, return the stored
    // result without changing the score.
    const existing = await client.query(
      `SELECT correct FROM answers WHERE game_id = $1 AND question_id = $2`,
      [gameId, questionId]
    );
    if (existing.rows.length > 0) {
      const wasCorrect = existing.rows[0].correct;
      const score = await computeScore(client, gameId);
      return { correct: wasCorrect, score };
    }

    // Record the answer.
    await client.query(
      `INSERT INTO answers (game_id, question_id, answer, correct)
       VALUES ($1, $2, $3, $4)`,
      [gameId, questionId, String(answer), correct]
    );

    // Increment the persisted score only when correct (each correct = 1).
    if (correct) {
      const currentScore =
        typeof gameState.score === 'number' ? gameState.score : 0;
      await client.query(
        `UPDATE games SET game_state = $1 WHERE id = $2`,
        [JSON.stringify(Object.assign({}, gameState, { score: currentScore + 1 })), gameId]
      );
    }

    const score = await computeScore(client, gameId);
    return { correct, score };
  });
}

async function computeScore(client, gameId) {
  const result = await client.query(
    `SELECT COUNT(*)::int AS correct_count
       FROM answers
      WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].correct_count;
}

/**
 * Get the current score for a game. Enforces ownership (other user -> 403).
 */
async function getScore(pool, gameId, ownerUserId) {
  const game = await getGame(pool, gameId);
  if (!game) {
    const err = new DbError('Game not found', 'NOT_FOUND');
    err.status = 404;
    throw err;
  }
  if (game.ownerUserId !== ownerUserId) {
    const err = new DbError('Not authorized for this game', 'FORBIDDEN');
    err.status = 403;
    throw err;
  }
  const result = await pool.query(
    `SELECT COUNT(*)::int AS score FROM answers WHERE game_id = $1 AND correct = true`,
    [gameId]
  );
  return result.rows[0].score;
}

/**
 * Transition a game lifecycle state (pause/resume). Returns the new state.
 * Enforces ownership; invalid transition -> 409.
 */
async function transitionGame(pool, gameId, ownerUserId, transitionFn) {
  return withTransaction(pool, async (client) => {
    const ownerResult = await client.query(
      `SELECT owner_user_id FROM games_owners WHERE game_id = $1`,
      [gameId]
    );
    if (ownerResult.rows.length === 0) {
      const err = new DbError('Game not found', 'NOT_FOUND');
      err.status = 404;
      throw err;
    }
    if (ownerResult.rows[0].owner_user_id !== ownerUserId) {
      const err = new DbError('Not authorized for this game', 'FORBIDDEN');
      err.status = 403;
      throw err;
    }

    const gameResult = await client.query(
      `SELECT game_state FROM games WHERE id = $1 FOR UPDATE`,
      [gameId]
    );
    const gameState =
      typeof gameResult.rows[0].game_state === 'string'
        ? JSON.parse(gameResult.rows[0].game_state)
        : gameResult.rows[0].game_state;

    let nextState;
    try {
      nextState = transitionFn(gameState);
    } catch (stateErr) {
      const err = new DbError(stateErr.message, 'INVALID_TRANSITION');
      err.status = 409;
      throw err;
    }

    await client.query(
      `UPDATE games SET game_state = $1 WHERE id = $2`,
      [JSON.stringify(nextState), gameId]
    );
    return nextState.state;
  });
}

module.exports = {
  DbError,
  createPool,
  migrate,
  upsertUser,
  withTransaction,
  createGame,
  getGame,
  submitAnswer,
  getScore,
  transitionGame,
};

'use strict';

/**
 * Process bootstrap for the Space Fractions gateway.
 *
 * Constructs the concrete infrastructure adapters (PostgreSQL pool, Redis
 * cache, RabbitMQ score events, Elasticsearch search client, Prometheus
 * metrics) using process environment variables, then builds the Express app via
 * createApp(...) and starts the HTTP server. All integrations degrade
 * gracefully when their backing service is absent or disabled (assumption A-6),
 * so the gateway remains reachable (GET /health -> 200) with PostgreSQL alone.
 *
 * Environment variables respected here (see .env.example):
 *   PORT                  HTTP listen port (default 3000 for the Compose
 *                          browser gateway contract).
 *   DATABASE_URL          PostgreSQL connection string / config (lib/db.js).
 *   REDIS_URL             Redis URL (lib/cache.js).
 *   RABBITMQ_URL          AMQP URL (lib/events.js).
 *   ELASTICSEARCH_URL     Elasticsearch node (lib/search.js).
 *   DISABLED_FEATURES     Comma-separated feature names to disable
 *                          (redis|rabbitmq|elasticsearch|metrics).
 *   OIDC_ISSUER           Public issuer used to validate tokens.
 *   OIDC_JWKS_URI         Internal JWKS URL (defaults to issuer + certs path).
 *   OIDC_AUDIENCE         Expected access-token audience (optional).
 *   REQUIRE_AUTH          "false" disables mandatory auth (dev/test only).
 */

const { createPool, migrate } = require('../lib/db');
const { createCache } = require('../lib/cache');
const { createEventEmitter } = require('../lib/events');
const { createSearchClient } = require('../lib/search');
const { createApp } = require('./app');

function parseDisabledFeatures(raw) {
  const value = (raw || process.env.DISABLED_FEATURES || '');
  return new Set(
    String(value)
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean)
  );
}

function parsePort() {
  const port = Number(process.env.PORT || 3000);
  return Number.isInteger(port) && port > 0 ? port : 3000;
}

/**
 * Build the metrics registry (prom-client). Returns null when disabled so the
 * /metrics endpoint still answers 200 with an empty exposition.
 */
function buildMetrics(disabled) {
  if (disabled.has('metrics')) return null;
  try {
    // eslint-disable-next-line global-require
    const client = require('prom-client');
    const registry = new client.Registry();
    client.collectDefaultMetrics({ register: registry });
    return {
      metrics: () => registry.metrics(),
      contentType: registry.contentType,
    };
  } catch (err) {
    // prom-client is a declared dependency; if it is not installed this must
    // surface rather than silently degrade to a fake metrics endpoint.
    console.warn(`metrics disabled: prom-client unavailable (${err.message})`);
    return null;
  }
}

async function main() {
  const disabled = parseDisabledFeatures();
  const requireAuth = process.env.REQUIRE_AUTH !== 'false';

  const pool = createPool(process.env.DATABASE_URL || undefined);

  // Apply idempotent migrations on startup; failure is fatal because PostgreSQL
  // is the system of record and the gateway cannot serve correct game state
  // without it. (Space Fractions migrations are idempotent by construction.)
  try {
    const applied = await migrate(pool);
    console.log(`migrations applied: ${applied.join(', ')}`);
  } catch (err) {
    console.error(`migration failed: ${err.message}`);
    pool.end().catch(() => {});
    process.exit(1);
  }

  const cache = createCache({ disabled });
  const events = createEventEmitter({ disabled });
  const searchClient = createSearchClient({ disabled });
  const metrics = buildMetrics(disabled);

  const app = createApp({
    pool,
    cache,
    events,
    searchClient,
    metrics,
    verifierOptions: {},
    requireAuth,
  });

  const port = parsePort();
  const server = app.listen(port, () => {
    console.log(`Space Fractions gateway listening on 0.0.0.0:${port}`);
  });

  const shutdown = (signal) => {
    console.log(`${signal} received, shutting down`);
    server.close(() => {
      pool.end()
        .catch(() => {})
        .finally(() => process.exit(0));
    });
    // Force-exit if connections do not drain promptly.
    setTimeout(() => process.exit(1), 5000).unref();
  };

  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

main().catch((err) => {
  console.error(`gateway failed to start: ${err && err.stack ? err.stack : err}`);
  process.exit(1);
});
